    let body = fold_short_circuits(
        &body,
        &proven_locals,
        refs,
        fields,
        &HashMap::new(),
        class_name,
        &retained_bool_branches,
    );
    pass_trace("fold_short_circuits", &body);
    let body = join_short_circuit_chains(&body);
    pass_trace("join_short_circuit_chains", &body);
