    #[test]
    fn native_name_initializers_reject_wrong_identity_width_lives_and_overloads() {
        let class = native_name_initializer_fixture();
        let refs = RefResolver::from_test_native_name_initializer(0);
        for fault in 1..=9 {
            let keep = super::native_field_initializer_prefix(&class, "Module", &RefResolver::from_test_native_name_initializer(fault));
            assert!(!keep.contains("NameA") && !keep.contains("TimeA"), "fault={fault} {keep:?}");
        }
        assert!(super::native_field_initializer_prefix(&class, "WrongModule", &refs).is_empty());
        for (object_const, read_only) in [(true, false), (false, true)] {
            let mut partial = class.clone();
            partial.fields[3].ty.is_object_const = object_const; partial.fields[3].ty.is_read_only = read_only;
            let keep = super::native_field_initializer_prefix(&partial, "Module", &refs);
            assert!(!keep.contains("NameA") && !keep.contains("TimeA"));
        }
        for (object_const, read_only) in [(true, false), (false, true), (true, true)] {
            let mut constant_scalar = class.clone();
            constant_scalar.fields[0].ty.is_object_const = object_const; constant_scalar.fields[0].ty.is_read_only = read_only;
            assert!(!super::native_field_initializer_prefix(&constant_scalar, "Module", &refs).contains("TimeA"));
        }
        let mut wrong_type = class.clone(); wrong_type.fields[1].ty.token = 0x50;
        assert!(!super::native_field_initializer_prefix(&wrong_type, "Module", &refs).contains("TimeA"));
        let mut reversed = class.clone(); reversed.fields.swap(0, 1);
        assert!(super::native_field_initializer_prefix(&reversed, "Module", &refs).is_empty());
        let mut branch = class.clone(); branch.ctors[0].bytecode.extend(function(&[("JMP", &[])]).bytecode);
        assert!(super::native_field_initializer_prefix(&branch, "Module", &refs).is_empty());
        let mut reused = class.clone();
        let mut read = function(&[("LoadThisR", &[24]), ("RDR8", &[6])]); read.bytecode[1] = 11;
        reused.ctors[0].bytecode.extend(read.bytecode);
        assert!(!super::native_field_initializer_prefix(&reused, "Module", &refs).contains("TimeA"));
        let mut wrong_copy = class.clone(); let code = super::disassemble(&wrong_copy.ctors[0].bytecode).unwrap();
        wrong_copy.ctors[0].bytecode[code[14].offset_dw + 1] = 8;
        let mut overload = class.clone(); overload.ctors.extend(wrong_copy.ctors);
        assert!(!super::native_field_initializer_prefix(&overload, "Module", &refs).contains("NameA"));
        let fields = HashSet::from(["TimeA", "TimeB", "Enabled", "NameA", "NameB"]);
        let keep = super::native_field_initializer_prefix(&class, "Module", &refs);
        let first = "    Example()\n    {\n        this.TimeA = 0.0;\n        this.NameA = n\"First\";\n        Work();\n        return;\n    }\n";
        let other = first.replace("Example()", "Example(bool flag)").replace("n\"First\"", "n\"Other\"");
        let mut source = format!("{first}{other}");
        let lifted = super::extract_member_initializers_with_native_prefix(&mut source, &fields, &keep);
        assert_eq!(lifted, HashMap::from([("TimeA".into(), "0.0".into())]));
        assert_eq!(source.matches("this.NameA =").count(), 2);
        let mut source = first.replace("this.TimeA = 0.0;", "Prepare();\n        this.TimeA = 0.0;");
        let unchanged = source.clone();
        assert!(super::extract_member_initializers_with_native_prefix(&mut source, &fields, &keep).is_empty());
        assert_eq!(source, unchanged);
    }
    #[test]
    fn native_field_initializer_prefix_keeps_ctor_work_and_overload_consensus() {
        let fields = HashSet::from(["Path", "Kind"]);
        let keep = HashSet::from(["Path".to_owned(), "Kind".to_owned()]);
        let first = "    Example()\n    {\n        this.Path = MakePath();\n        this.Kind = StaticClass();\n        Trigger();\n        return;\n    }\n";
        let other = "    Example(bool flag)\n    {\n        this.Path = MakePath();\n        this.Kind = StaticClass();\n        if (flag)\n        {\n            Work();\n        }\n        return;\n    }\n";
        let mut source = format!("{first}{other}");
        assert_eq!(super::extract_member_initializers_with_native_prefix(&mut source, &fields, &keep).len(), 2);
        assert!(source.contains("Trigger();") && source.contains("if (flag)"));
        let original = format!("{first}{}", other.replace("MakePath()", "OtherPath()"));
        let mut source = original.clone();
        assert!(super::extract_member_initializers_with_native_prefix(&mut source, &fields, &keep).is_empty());
        assert_eq!(source, original);
        let mut source = first.to_owned();
        assert!(super::extract_member_initializers_with_native_prefix(&mut source, &fields, &HashSet::from(["Kind".into()])).is_empty());
        assert_eq!(source, first); // no moving Kind past the unsupported earlier Path store
        let mut source = first.replace("Example()", "Example(FName Path)").replace("MakePath()", "Path");
        assert!(super::extract_member_initializers_with_native_prefix(&mut source, &fields, &keep).is_empty());
    }

    #[test]
    fn direct_native_field_constructor_requires_own_typed_single_initialization() {
        let mut f = function(&[("PshC4", &[]), ("CALLSYS", &[]), ("PshRPtr", &[]),
            ("PshVPtr", &[0]), ("ADDSi", &[8]), ("CALLSYS", &[]), ("RET", &[2])]);
        f.name = "Example".into(); f.namespace = "NS".into(); f.ret.token = 0x52;
        let code = super::disassemble(&f.bytecode).unwrap();
        for (at, value) in [(1, 1), (4, 11), (5, 2)] { f.bytecode[code[at].offset_dw + 1] = value; }
        let class = |f| super::Class { name: "Example".into(), namespace: "NS".into(), super_class: None,
            fields: vec![super::super::model::Field { name: "Path".into(), ty: DataType { token: 5, type_info: 201, ..Default::default() }, is_uproperty: true }],
            methods: Vec::new(), ctors: vec![f], flags: 1 };
        let refs = RefResolver::from_test_native_direct_field(0);
        assert_eq!(super::directly_constructed_native_fields(&class(f.clone()), "Module", &refs), HashSet::from(["Path".into()]));
        let mut source = String::new();
        super::emit_class(&mut source, &class(f.clone()), "Module", &refs, None);
        assert!(source.contains("FSoftValue Path(n\"/Game/Example\");"), "{source}");
        for fault in 1..=7 {
            assert!(super::directly_constructed_native_fields(&class(f.clone()), "Module", &RefResolver::from_test_native_direct_field(fault)).is_empty());
        }
        assert!(super::directly_constructed_native_fields(&class(f.clone()), "OtherModule", &refs).is_empty());
        let mut inherited = class(f.clone()); inherited.fields.clear();
        assert!(super::directly_constructed_native_fields(&inherited, "Module", &refs).is_empty());
        let mut handles = class(f.clone()); handles.fields[0].ty.is_object_handle = true;
        assert!(super::directly_constructed_native_fields(&handles, "Module", &refs).is_empty());
        let mut duplicate = f.clone(); duplicate.bytecode.extend(f.bytecode.clone());
        assert!(super::directly_constructed_native_fields(&class(duplicate), "Module", &refs).is_empty());
        let mut branch = f.clone(); branch.bytecode.extend(function(&[("JMP", &[])]).bytecode);
        assert!(super::directly_constructed_native_fields(&class(branch), "Module", &refs).is_empty());
        let mut other = f.clone(); other.bytecode[code[5].offset_dw + 1] = 3;
        let mut overloads = class(f); overloads.ctors.push(other);
        assert!(super::directly_constructed_native_fields(&overloads, "Module", &refs).is_empty());
    }

    #[test]
    fn native_field_initializer_sites_require_both_typed_rhs_forms_and_own_identity() {
        let refs = RefResolver::from_test_native_field_initializer(0);
        let mut f = function(&[("PshC4", &[]), ("CALLSYS", &[]), ("PshRPtr", &[]),
            ("PshVPtr", &[0]), ("ADDSi", &[8]), ("CALLSYS", &[]), ("PshVPtr", &[0]), ("ADDSi", &[8]), ("CALLSYS", &[]),
            ("CALL", &[]), ("STOREOBJ", &[4]), ("PshVPtr", &[4]),
            ("PshVPtr", &[0]), ("ADDSi", &[16]), ("CALLSYS", &[]), ("PshVPtr", &[0]), ("ADDSi", &[16]), ("CALLSYS", &[]), ("RET", &[2])]);
        f.obj_locals = vec![(4, 302)];
        let code = super::disassemble(&f.bytecode).unwrap();
        for (at, value) in [(1, 1), (4, 11), (5, 2), (7, 11), (8, 3), (9, 44), (13, 11), (14, 5), (16, 11), (17, 6)] {
            f.bytecode[code[at].offset_dw + 1] = value;
        }
        let class = |f| super::Class { name: "Example".into(), namespace: "NS".into(), super_class: None,
            fields: vec![super::super::model::Field { name: "Path".into(), ty: DataType { token: 5, type_info: 201, ..Default::default() }, is_uproperty: true },
                super::super::model::Field { name: "Kind".into(), ty: DataType { token: 5, type_info: 202, ..Default::default() }, is_uproperty: true }],
            methods: Vec::new(), ctors: vec![f], flags: 1 };
        assert_eq!(super::native_field_initializer_prefix(&class(f.clone()), "Module", &refs), HashSet::from(["Path".into(), "Kind".into()]));
        assert_eq!(super::native_field_initializer_prefix(&class(f.clone()), "Module", &RefResolver::from_test_native_field_initializer(6)), HashSet::from(["Path".into(), "Kind".into()]));
        for fault in [1, 2, 3, 4, 5, 7, 8, 9] {
            assert_ne!(super::native_field_initializer_prefix(&class(f.clone()), "Module", &RefResolver::from_test_native_field_initializer(fault)).len(), 2);
        }
        assert!(super::native_field_initializer_prefix(&class(f.clone()), "OtherModule", &refs).is_empty());
        let mut overloads = class(f.clone());
        let mut unsupported = f.clone(); unsupported.bytecode[code[5].offset_dw + 1] = 1;
        overloads.ctors.push(unsupported);
        assert_eq!(super::native_field_initializer_prefix(&overloads, "Module", &refs), HashSet::from(["Kind".into()]));
        let mut branch = f;
        let jump = function(&[("JMP", &[])]); branch.bytecode.extend(jump.bytecode);
        let end = super::disassemble(&branch.bytecode).unwrap().last().unwrap().offset_dw;
        branch.bytecode[end + 1] = code[4].offset_dw as i32 - end as i32 - 2;
        assert!(super::native_field_initializer_prefix(&class(branch), "Module", &refs).is_empty());
    }

