    #[test]
    fn implicit_reference_copies_keep_exact_type_and_callee_across_declared_lives() {
        let refs = RefResolver::from_test_reference_copy_initializers(true, true);
        let f = reference_copy_initializer_fixture();
        let sites = super::reference_copy_initializer_sites(&f, &refs, &[(24, 3), (24, 7)]);
        assert_eq!(sites.len(), 2);
        let body = "    FBox local_24 = FBox(Make().First());\n    Use(local_24);\n    FBox local_24_2 = FBox(Make().Second());\n    Use(local_24_2);\n";
        let folded = super::drop_redundant_conversions(body, None, &HashMap::new(), &refs, &sites, &HashSet::new());
        assert_eq!(folded, "    FBox local_24 = Make().First();\n    Use(local_24);\n    FBox local_24_2 = Make().Second();\n    Use(local_24_2);\n");
        for other in ["    FBox local_24 = FBox(Make().Unknown());\n",
            "    FOther local_24 = FOther(Make().First());\n",
            "    local_24 = FBox(Make().First());\n"]
        {
            assert_eq!(super::drop_redundant_conversions(other, None, &HashMap::new(), &refs, &sites, &HashSet::new()), other);
        }
    }

    #[test]
    fn reference_copy_initializers_reject_nonreference_mixed_types_and_other_slot_producers() {
        let f = reference_copy_initializer_fixture();
        for (by_ref, same_type) in [(false, true), (true, false)] {
            let refs = RefResolver::from_test_reference_copy_initializers(by_ref, same_type);
            assert!(super::reference_copy_initializer_sites(&f, &refs, &[]).is_empty());
        }
        let refs = RefResolver::from_test_reference_copy_initializers(true, true);
        let code = super::disassemble(&f.bytecode).unwrap();
        let mut other = f.clone();
        // One unmatched ctor life invalidates the other life's permission too.
        other.bytecode[code[4].offset_dw] = crate::cache::isa::OPCODES.iter()
            .find(|op| op.name == "PshC8").unwrap().opcode as i32;
        assert!(super::reference_copy_initializer_sites(&other, &refs, &[]).is_empty());
        assert!(super::reference_copy_initializer_sites(&f, &refs, &[(24, 0)]).is_empty());
        let mut other = f.clone();
        other.bytecode.extend(function(&[("CpyRtoV4", &[24])]).bytecode);
        assert!(super::reference_copy_initializer_sites(&other, &refs, &[]).is_empty());
        let mut other = f.clone(); other.obj_locals[0].1 = 102;
        assert!(super::reference_copy_initializer_sites(&other, &refs, &[]).is_empty());
    }

    #[test]
    fn literal_bool_arguments_do_not_borrow_another_lifes_permission() {
        let ops: Vec<(&str, &[u16])> = vec![
            ("CpyRtoV4", &[3]), ("NOT", &[3]), ("SetV1", &[3]), ("PshV4", &[3]),
        ];
        let body = "    bool local_3 = false;\n    Trace(local_3);\n";
        let f = function(&ops);
        let candidates = super::pushed_bool_literal_defs(&f, body);
        assert_eq!(candidates, HashSet::from([(3, 1)]));
        let folded = inline_unnamed_value_temporaries(body, &candidates, &HashSet::new(),
            &HashSet::new(), &RefResolver::default(), &HashSet::new(), &HashSet::new(),
            &HashMap::new(), &HashSet::new(), &HashSet::new(), &HashSet::new(), &HashSet::new());
        assert_eq!(folded, "    Trace(false);\n");
        for source in [body.replace("false", "true"), body.replace("bool ", "int ")] {
            assert!(super::pushed_bool_literal_defs(&f, &source).is_empty());
        }
        for extra in [("PSF", &[3][..]), ("SetV4", &[3][..]), ("CpyVtoV4", &[3, 4][..])] {
            let mut other = ops.clone(); other.push(extra);
            assert!(super::pushed_bool_literal_defs(&function(&other), body).is_empty());
        }
        let mut delayed = ops.clone(); delayed.insert(3, ("PshC4", &[]));
        assert!(super::pushed_bool_literal_defs(&function(&delayed), body).is_empty());
        let mut address = ops; address[3] = ("PSF", &[3]);
        assert!(super::pushed_bool_literal_defs(&function(&address), body).is_empty());
    }

    fn conditional_constructor_arguments_fixture() -> Func {
        let mut f = function(&[
            ("SetV4", &[2]), ("SetV4", &[1]), ("CMPIi", &[1]), ("JNZ", &[]),
            ("SetV4", &[15]), ("JMP", &[]), ("SetV4", &[15]),
            ("PshC8", &[]), ("iTOd", &[26, 15]), ("PshV8", &[26]),
            ("CpyVtoV4", &[14, 2]), ("NEGi", &[14]), ("iTOd", &[28, 14]),
            ("PshV8", &[28]), ("PSF", &[22]), ("CALLSYS", &[]),
            ("PSF", &[22]), ("PshVPtr", &[(-2i16) as u16]), ("CALLSYS", &[]), ("RET", &[4]),
        ]);
        f.ret = DataType { token: 5, type_info: 101, ..Default::default() };
        f.obj_locals = vec![(22, 101)];
        let code = disassemble(&f.bytecode).unwrap();
        for (at, value) in [(0, 8), (4, 1), (6, -1), (15, 1), (18, 2)] {
            f.bytecode[code[at].offset_dw + 1] = value;
        }
        for (at, target) in [(3, 6), (5, 7)] {
            f.bytecode[code[at].offset_dw + 1] = code[target].offset_dw as i32 - code[at].offset_dw as i32 - 2;
        }
        f
    }

    #[test]
    fn conditional_producer_keeps_its_numeric_type_before_a_widening_copy() {
        let refs = RefResolver::default();
        let body = "    local_15 = local_1 == 0 ? 1 : -1;\n    local_26 = local_15;\n";
        let fold = |text: &str, from: &str, to: &str| {
            let locals = BTreeMap::from([(1, "int".into()), (15, from.into()), (26, to.into())]);
            super::inline_call_argument_temporaries(text, &refs, &locals, None, true, &HashMap::new(),
                &HashSet::new(), &HashSet::new(), &HashSet::new(), &HashSet::new(), &HashSet::new(),
                &HashSet::new(), &HashSet::new(), &HashSet::new(), &HashMap::new(), &HashSet::new(), &HashSet::new())
        };
        assert_eq!(fold(body, "int", "float"), body);
        assert_eq!(fold(body, "float", "int"), body);
        assert_eq!(fold(body, "int", "int"), "    local_26 = local_1 == 0 ? 1 : -1;\n");
        // Canonical aliases agree; a non-conditional scalar copy keeps the old path.
        assert_eq!(fold(body, "double", "float"), "    local_26 = local_1 == 0 ? 1 : -1;\n");
        let plain = body.replace("local_1 == 0 ? 1 : -1", "local_1");
        assert_eq!(fold(&plain, "int", "float"), "    local_26 = local_1;\n");
    }

    #[test]
    fn conditional_and_copied_negation_survive_then_inline_at_their_constructor_arguments() {
        let f = conditional_constructor_arguments_fixture();
        let refs = RefResolver::from_test_conditional_constructor_arguments(0);
        let negation = super::copied_integer_negation_arguments(&f, &refs);
        assert_eq!(negation, HashSet::from([14]));
        assert!(!super::arithmetic_temporaries(&f).contains(&14));
        assert!(super::arithmetic_temporaries(&f).contains(&15));
        let locals = BTreeMap::from([(1, "int".into()), (2, "int".into()), (14, "int".into()),
            (15, "int".into()), (26, "float".into()), (28, "float".into())]);
        let body = "    int local_15 = local_1 == 0 ? 1 : -1;\n    float local_26 = local_15;\n    int local_14 = local_2;\n    local_14 = -local_14;\n    float local_28 = local_14;\n    return FVector(local_28, local_26, 0.0);\n";
        let fold = |text: &str, extra: &HashSet<i32>| {
            let arithmetic = super::arithmetic_temporaries(&f).union(extra).copied().collect();
            // The raw iTOd results are unnamed; the integer conditional is not.
            let unnamed = HashSet::from([(26, 1), (28, 1)]);
            let inline = |s: &str| inline_unnamed_value_temporaries(s, &unnamed, &HashSet::new(),
                &HashSet::new(), &refs, &arithmetic, &HashSet::new(), &HashMap::new(), &HashSet::new(),
                &HashSet::new(), &HashSet::new(), &HashSet::new());
            let mut out = super::merge_self_assignments(&inline(text), &locals);
            for _ in 0..3 { out = inline(&out); }
            super::fold_widening_aliases(&out, &locals, &HashMap::new(), &HashSet::new())
        };
        let expected = "    int local_15 = local_1 == 0 ? 1 : -1;\n    return FVector(-local_2, local_15, 0.0);\n";
        assert_eq!(fold(body, &negation), expected);
        let old = fold(body, &HashSet::new());
        assert!(old.contains("int local_14 = -local_2;"), "{old}");
        assert_ne!(old, expected);
        let later_life = body.replace("local_14", "local_14_2");
        assert!(fold(&later_life, &negation).contains("int local_14_2 = -local_2;"));
        let calls = body.replace("local_14 = -local_14", "local_14 = -ReadIndex()");
        assert!(fold(&calls, &negation).contains("local_14 = -ReadIndex();"));
    }

    #[test]
    fn copied_integer_negation_requires_exact_types_closed_lives_and_argument_entry() {
        let f = conditional_constructor_arguments_fixture();
        for fault in 1..=10 {
            let refs = RefResolver::from_test_conditional_constructor_arguments(fault);
            assert!(super::copied_integer_negation_arguments(&f, &refs).is_empty(), "metadata {fault}");
        }
        let refs = RefResolver::from_test_conditional_constructor_arguments(0);
        let code = disassemble(&f.bytecode).unwrap();
        for (at, name) in [(10, "CpyVtoV8"), (11, "NEGf"), (12, "iTOf"), (13, "PSF")] {
            let mut wrong = f.clone();
            let opcode = OPCODES.iter().find(|op| op.name == name).unwrap().opcode as i32;
            wrong.bytecode[code[at].offset_dw] = (wrong.bytecode[code[at].offset_dw] & !0xff) | opcode;
            assert!(super::copied_integer_negation_arguments(&wrong, &refs).is_empty(), "{name}");
        }
        for extra in [("PSF", &[14][..]), ("SetV4", &[14][..]), ("PshV8", &[28][..])] {
            let mut reused = f.clone(); reused.bytecode.extend(function(&[extra]).bytecode);
            assert!(super::copied_integer_negation_arguments(&reused, &refs).is_empty());
        }
        let mut entry = f.clone();
        entry.bytecode[code[5].offset_dw + 1] = code[12].offset_dw as i32 - code[5].offset_dw as i32 - 2;
        assert!(super::copied_integer_negation_arguments(&entry, &refs).is_empty());
        let mut untyped = f.clone(); untyped.obj_locals.clear();
        assert!(super::copied_integer_negation_arguments(&untyped, &refs).is_empty());
        let mut duplicate = f.clone(); duplicate.obj_locals.push((22, 101));
        assert!(super::copied_integer_negation_arguments(&duplicate, &refs).is_empty());
        let mut object_scratch = f.clone(); object_scratch.obj_locals.push((14, 101));
        assert!(super::copied_integer_negation_arguments(&object_scratch, &refs).is_empty());
    }

    #[test]
    fn copied_widening_negation_requires_its_whole_physical_slot_profile() {
        let code: Vec<(&str, &[u16])> = vec![
            ("fTOd", &[10, 7]), ("CpyVtoV8", &[6, 10]),
            ("CpyVtoV8", &[10, 6]), ("NEGd", &[10]), ("PshV8", &[10]),
        ];
        let f = function(&code);
        assert!(super::strict_f64_arithmetic_temp_slots(&f).contains(&10));
        let body = "    float local_10;\n    float local_6 = ReadAge();\n    local_10 = -(local_6);\n    this.Held = Math::Max(0.0, local_10);\n";
        let fold = |text: &str, witnesses: &HashSet<i32>| inline_unnamed_value_temporaries(
            text, &HashSet::new(), &HashSet::new(), &HashSet::new(), &RefResolver::default(),
            &HashSet::new(), &HashSet::new(), &HashMap::new(), &HashSet::new(),
            &HashSet::new(), &HashSet::new(), witnesses);
        let witnesses = super::strict_f64_arithmetic_temp_slots(&f);
        assert_eq!(fold(body, &witnesses),
            "    float local_6 = ReadAge();\n    this.Held = Math::Max(0.0, -(local_6));\n");
        assert_eq!(fold(body, &HashSet::new()), body);
        let call = body.replace("-(local_6)", "-(ReadAge())");
        assert_eq!(fold(&call, &witnesses), call);
        let separated = body.replace("    this.Held", "    Observe();\n    this.Held");
        assert_eq!(fold(&separated, &witnesses), separated);
        for (at, replacement) in [
            (0, ("fTOd", &[10, 10][..])),
            (1, ("CpyVtoV8", &[6, 12][..])),
            (2, ("CpyVtoV8", &[10, 8][..])),
            (3, ("NEGf", &[10][..])),
            (4, ("PSF", &[10][..])),
        ] {
            let mut other=code.clone(); other[at]=replacement;
            assert!(!super::strict_f64_arithmetic_temp_slots(&function(&other)).contains(&10));
        }
        for extra in [("PSF", &[10][..]), ("SetV8", &[10][..])] {
            let mut other=code.clone(); other.push(extra);
            assert!(!super::strict_f64_arithmetic_temp_slots(&function(&other)).contains(&10));
        }
    }

    fn bool_field_return_fixture(field: &str, field_type: Option<&str>) -> (Func, RefResolver) {
        // The real AssessmentBits branch tail: wide zero in one arm, a byte bool
        // field copied in the other, then CpyVtoR4/RET. A null guard substitutes
        // for IsValid here so the test needs no unrelated native-call metadata.
        let code: Vec<(&str, &[u16])> = vec![
            ("CmpPtrNull", &[0]), ("JNZ", &[]), ("SetV4", &[5]), ("JMP", &[]),
            ("LoadRObjR", &[0, 0]), ("RDR1", &[6]), ("CpyVtoV4", &[5, 6]),
            ("CpyVtoR4", &[5]), ("RET", &[2]),
        ];
        let mut f = function(&code);
        f.ret.token = 0x41;
        f.params.push(crate::cache::model::Param {
            name: "Value".into(), flags: 0,
            ty: DataType { token: 5, type_info: 1, is_object_handle: true, ..Default::default() },
        });
        let ins = super::disassemble(&f.bytecode).unwrap();
        f.bytecode[ins[4].offset_dw + 2] = 1; // exact field owner type id
        for (from, to) in [(1, 4), (3, 7)] {
            f.bytecode[ins[from].offset_dw + 1] =
                ins[to].offset_dw as i32 - ins[from].offset_dw as i32 - 2;
        }
        let mut refs = RefResolver::from_test_member_chain(&[("UAIValueSet_Crime", field)]);
        if let Some(ty) = field_type {
            refs.set_class_fields(HashMap::from([("UAIValueSet_Crime".into(),
                HashMap::from([(field.into(), ty.into())]))]));
        }
        (f, refs)
    }

    #[test]
    fn bool_field_return_merges_keep_their_type_through_the_wide_store_veto() {
        for field in ["bWitnessIsPersonalVictim", "bWitnessIsAreaEnforcer", "bVictimIsOutgroup",
            "bIsReputationEscalated", "bIsReputationAtExecuteLevel"]
        {
            let (f, refs) = bool_field_return_fixture(field, Some("bool"));
            assert_eq!(super::canonical_bool_return_slots(&f, &refs), HashSet::from([5]));
            let mut source = String::new();
            super::emit_function(&mut source, &f, &refs, false, false, 0);
            assert!(source.contains(&format!("Value.{field}")), "{source}");
            assert!(!source.contains("int local_5") && !source.contains("!= 0"), "{source}");
        }
    }

    #[test]
    fn bool_field_return_proof_rejects_unknown_types_and_other_slot_lives() {
        for ty in [None, Some("EByteStatus"), Some("uint8"), Some("int")] {
            let (f, refs) = bool_field_return_fixture("bWitnessIsPersonalVictim", ty);
            assert!(super::canonical_bool_return_slots(&f, &refs).is_empty(), "{ty:?}");
        }
        let (f, refs) = bool_field_return_fixture("bWitnessIsPersonalVictim", Some("bool"));
        for value in [1, 2, 256] {
            let mut other = f.clone();
            let ins = super::disassemble(&other.bytecode).unwrap();
            other.bytecode[ins[2].offset_dw + 1] = value;
            assert!(super::canonical_bool_return_slots(&other, &refs).is_empty());
        }
        for extra in [
            ("RDR1", &[6][..]), // another unproved field-read life of the source
            ("SetV1", &[6][..]),
            ("CpyVtoV4", &[6, 8][..]),
            ("PSF", &[6][..]),
            ("PshV4", &[5][..]), // a non-return consumer of the merge slot
        ] {
            let mut other = f.clone();
            other.bytecode.extend(function(&[extra]).bytecode);
            assert!(super::canonical_bool_return_slots(&other, &refs).is_empty(), "{extra:?}");
        }
        let mut separated = f.clone();
        let ins = super::disassemble(&separated.bytecode).unwrap();
        separated.bytecode.splice(ins[6].offset_dw..ins[6].offset_dw,
            function(&[("SUSPEND", &[])]).bytecode);
        assert!(super::canonical_bool_return_slots(&separated, &refs).is_empty());
    }

