    fn terminal_bool_return_scope_requires_the_direct_call_and_exit_jump() {
        for native in [false, true] {
            let mut f = function(&[(if native { "CALLSYS" } else { "CALL" }, &[]),
                ("CpyRtoV4", &[9]), ("CpyVtoR4", &[9]), ("JMP", &[]), ("RET", &[0])]);
            f.ret.token = 0x41;
            f.bytecode[1] = if native { 2 } else { 1 };
            let refs = if native { RefResolver::from_test_retained_receiver(0x41, true) }
                else { RefResolver::from_test_script_result(DataType { token: 0x41, ..Default::default() }) };
            let call = if native { "Count" } else { "Read" };
            let body = format!("    UActor local_2 = Actor;\n    return local_2.Component().{call}();\n");
            let expected = format!("    UActor local_2 = Actor;\n    {{\n        return local_2.Component().{call}();\n    }}\n");
            assert_eq!(super::restore_terminal_bool_return_scope(&body, &f, &refs), expected);
            assert_eq!(super::restore_terminal_bool_return_scope(&expected, &f, &refs), expected);
            let code = disassemble(&f.bytecode).unwrap();
            for fault in 0..5 {
                let mut other = f.clone();
                match fault {
                    0 => other.ret.token = 0x40,
                    1 => other.bytecode[1] = 99,
                    2 => other.bytecode[code[3].offset_dw + 1] = 1,
                    3 => other.bytecode[code[2].offset_dw] ^= (1 << 16),
                    _ => { other.bytecode.splice(0..0, function(&[("PshV4", &[9])]).bytecode); },
                }
                assert_eq!(super::restore_terminal_bool_return_scope(&body, &other, &refs), body, "{native}/{fault}");
            }
            for other in [body.replace(call, "Other"), format!("    if (Check())\n    {{\n        return true;\n    }}\n{body}")] {
                assert_eq!(super::restore_terminal_bool_return_scope(&other, &f, &refs), other);
            }
        }
    }

    #[test]
    fn terminal_bool_literal_return_requires_the_direct_raw_tail() {
        for value in 0..2 {
            let mut f = function(&[("SetV1", &[3]), ("CpyVtoR4", &[3]), ("RET", &[0])]);
            f.ret.token = 0x41; f.bytecode[1] = value;
            let literal = if value == 0 { "false" } else { "true" };
            let body = format!("    Work();\n    bool local_3_2 = {literal};\n    return local_3_2;\n");
            assert_eq!(super::fold_terminal_bool_literal_return(&body, &f),
                format!("    Work();\n    return {literal};\n"));
            for wrong in [body.replace("bool ", "int "), body.replace("local_3_2", "local_4_2"),
                format!("    Use(local_3_2);\n{body}"), format!("    if (Check())\n    {{\n{body}")]
            { assert_eq!(super::fold_terminal_bool_literal_return(&wrong, &f), wrong); }
            let mut other = f.clone(); other.ret.token = 0x44;
            assert_eq!(super::fold_terminal_bool_literal_return(&body, &other), body);
            let mut other = f.clone(); other.bytecode[1] = 1 - value;
            assert_eq!(super::fold_terminal_bool_literal_return(&body, &other), body);
            let mut other = function(&[("JMP", &[])]); other.ret = f.ret.clone();
            other.bytecode[1] = 2; other.bytecode.extend(f.bytecode.clone());
            assert_eq!(super::fold_terminal_bool_literal_return(&body, &other), body);
            other.bytecode[1] = 0; // An entry at SetV1 still initializes the returned literal.
            assert_ne!(super::fold_terminal_bool_literal_return(&body, &other), body);
        }
    }

    #[test]
    fn unused_native_handle_reader_keeps_its_single_typed_store() {
        let mut f = function(&[("PshVPtr", &[(-2i16) as u16]), ("CALLSYS", &[]),
            ("STOREOBJ", &[4]), ("RET", &[0])]);
        let code = disassemble(&f.bytecode).unwrap(); f.bytecode[code[1].offset_dw + 1] = 1;
        f.obj_locals = vec![(4, 1)];
        let refs = RefResolver::from_test_native_handle_reader(0);
        let keep = super::unused_script_handle_results(&f, &refs);
        assert_eq!(keep, HashSet::from([4]));
        let body = "    local_4 = Read(Target);\n    return false;\n";
        let locals = std::collections::BTreeMap::from([(4, "UValue".into())]);
        assert_eq!(super::drop_unread_call_results(body, &locals, &refs, &keep, &HashSet::new()).0, body);
        for fault in 1..8 {
            assert!(super::unused_script_handle_results(&f,
                &RefResolver::from_test_native_handle_reader(fault)).is_empty(), "fault={fault}");
        }
        for extra in [("STOREOBJ", &[4][..]), ("PshVPtr", &[4][..]), ("FreeNullV8", &[4][..])] {
            let mut other = f.clone(); other.bytecode.extend(function(&[extra]).bytecode);
            assert!(super::unused_script_handle_results(&other, &refs).is_empty());
        }
        let mut other = f.clone(); other.obj_locals.clear();
        assert!(super::unused_script_handle_results(&other, &refs).is_empty());
        let mut other = f.clone(); other.bytecode[0] &= 0xffff;
        assert!(super::unused_script_handle_results(&other, &refs).is_empty());
        let mut other = f.clone(); other.bytecode.extend(function(&[("JMP", &[])]).bytecode);
        let jump = disassemble(&other.bytecode).unwrap().pop().unwrap();
        other.bytecode[jump.offset_dw + 1] = code[2].offset_dw as i32 - jump.offset_dw as i32 - 2;
        assert!(super::unused_script_handle_results(&other, &refs).is_empty());
    }

    #[test]
    fn unreachable_keeps_switch_entries_after_return_and_break() {
        let body = "switch (Value)\n{\n    case 3:\n        return 2;\n        DeadA();\n    case 2:\n        break;\n        DeadB();\n    case 1:\n    default:\n        return 0;\n        DeadC();\n}\nAfterSwitch();\n";
        let expected = body.replace("        DeadA();\n", "").replace("        DeadB();\n", "")
            .replace("        DeadC();\n", "");
        assert_eq!(super::drop_unreachable_statements(body), expected);
        // Labels inside an already unreachable nested statement cannot revive it.
        let dead = format!("return;\n{body}");
        assert_eq!(super::drop_unreachable_statements(&dead), "return;\n");
        let nested = "switch (First)\n{\n    case 1:\n        switch (Second)\n        {\n            case 2:\n                return 2;\n            default:\n                break;\n        }\n        AfterNested();\n        break;\n    default:\n        return 0;\n}\nAfterOuter();\n";
        assert_eq!(super::drop_unreachable_statements(nested), nested);
    }

    #[test]
    fn unreachable_preserves_bare_block_after_if_else_and_loop_continuation() {
        let body = "    while (More())\n    {\n        if (Choose())\n        {\n            First();\n        }\n        else\n        {\n            Second();\n        }\n        {\n            Handle local_96 = local_98;\n            Use(local_96);\n        }\n        Advance();\n    }\n    SayMultiple();\n";
        assert_eq!(super::drop_unreachable_statements(body), body);
        let after_statement = "    Work();\n    {\n        Inner();\n    }\n    After();\n";
        assert_eq!(super::drop_unreachable_statements(after_statement), after_statement);
    }

    #[test]
    fn definite_assignment_walk_keeps_the_loop_state_across_bare_scopes() {
        let body = "    while (More())\n    {\n        local_89 = 0;\n        if (Choose())\n        {\n            local_89 = Next();\n        }\n        Use(local_89);\n        if (Choose())\n        {\n            First();\n        }\n        else\n        {\n            Second();\n        }\n        {\n            Use(local_89);\n        }\n    }\n    AfterLoop();\n";
        assert!(super::all_reads_lexically_dominated_by_assignment(body, 89));
        let outside = format!("{body}    Use(local_89);\n");
        assert!(!super::all_reads_lexically_dominated_by_assignment(&outside, 89));
        let unassigned = body.replace("        local_89 = 0;\n", "");
        assert!(!super::all_reads_lexically_dominated_by_assignment(&unassigned, 89));
    }

    #[test]
    fn unreachable_propagates_bare_block_exits_but_not_zero_iteration_loops() {
        for exit in ["return;", "return value;", "break;", "continue;"] {
            let body = format!("    while (More())\n    {{\n        Work();\n        {{\n            {exit}\n            DeadInBlock();\n        }}\n        DeadInLoop();\n    }}\n    AfterLoop();\n");
            let expected = body.replace("            DeadInBlock();\n", "")
                .replace("        DeadInLoop();\n", "");
            assert_eq!(super::drop_unreachable_statements(&body), expected, "{exit}");
        }
        let returning = "    Work();\n\n    {\n        {\n            return value;\n        }\n        DeadInOuter();\n    }\n    DeadAfter();\n";
        let expected = returning.replace("        DeadInOuter();\n", "")
            .replace("    DeadAfter();\n", "");
        assert_eq!(super::drop_unreachable_statements(returning), expected);
    }

    #[test]
    fn parameter_comparison_keeps_the_copy_before_the_member_read() {
        let refs = RefResolver::from_test_parameter_field_comparison(DataType::default(), false);
        let mut f = function(&[("PshVPtr", &[(-2i16) as u16]), ("RefCpyV", &[2]),
            ("PshVPtr", &[0]), ("ADDSi", &[0]), ("RDSPtr", &[]), ("RefCpyV", &[4]),
            ("CmpPtr", &[2, 4]), ("RET", &[4])]);
        f.ret.token = 0x52;
        f.params.push(crate::cache::model::Param { name: "Actor".into(), flags: 0,
            ty: DataType { token: 5, type_info: 2, is_object_handle: true, ..Default::default() } });
        f.obj_locals = vec![(2, 2), (4, 2)];
        let code = disassemble(&f.bytecode).unwrap(); f.bytecode[code[3].offset_dw + 1] = 1;
        let keep = super::parameter_member_comparison_copies(&f, &refs, true);
        assert_eq!(keep, HashSet::from([2]));
        let body = "    local_2 = Actor;\n    local_4 = this.Target;\n    if (local_2 == local_4)\n    {\n        this.Target = nullptr;\n    }\n";
        let locals = BTreeMap::from([(2, "UNode".into()), (4, "UNode".into())]);
        let roots = HashMap::from([("Actor".into(), "UNode".into())]);
        assert_eq!(super::fold_member_read_temporaries(body, &HashSet::new(), &HashSet::new(),
            &locals, None, &roots, &refs, &HashMap::new(), false, &keep,
            &HashSet::new(), &HashMap::new()), body);
        for fault in 0..5 {
            let mut other = f.clone();
            match fault {
                0 => other.params[0].ty.is_object_const = true,
                1 => other.obj_locals[1].1 = 1,
                2 => other.obj_locals.push((2, 2)),
                3 => other.bytecode.extend(function(&[("PshVPtr", &[2])]).bytecode),
                _ => other.bytecode[code[6].offset_dw + 1] ^= 1,
            }
            assert!(super::parameter_member_comparison_copies(&other, &refs, true).is_empty(), "{fault}");
        }
        assert!(super::parameter_member_comparison_copies(&f,
            &RefResolver::from_test_parameter_field_comparison(DataType::default(), true), true).is_empty());
        assert_eq!(super::parameter_member_comparison_copies(&f,
            &RefResolver::from_test_parameter_comparison_upcast(0), true), HashSet::from([2]));
        for fault in [1, 2] {
            assert!(super::parameter_member_comparison_copies(&f,
                &RefResolver::from_test_parameter_comparison_upcast(fault), true).is_empty());
        }
    }

