    fn nullguard_names_survive_after_their_slots_returned_earlier_literals() {
        let f = nullguard_after_literal_return_fixture();
        let refs = RefResolver::from_test_parameter_field_comparison(DataType::default(), false);
        let spilled = super::spilled_boolean_names(&f, &refs);
        assert_eq!(spilled, HashSet::from([3, 4, 7, 11]));
        let body = "    local_2 = Cast<UNode>(Actor);\n    local_3 = (local_2 != nullptr);\n    if (local_3)\n    {\n        return false;\n    }\n    local_6 = Cast<UNode>(Actor);\n    local_4 = (local_6 != nullptr);\n    if (local_4)\n    {\n        return false;\n    }\n    local_10 = Cast<UNode>(Actor);\n    local_7 = (local_10 != nullptr);\n    if (local_7)\n    {\n        return false;\n    }\n    local_14 = Cast<UNode>(Actor);\n    local_11 = (local_14 != nullptr);\n    if (local_11)\n    {\n        return true;\n    }\n    return true;\n";
        let locals = BTreeMap::from([(2, "UNode".into()), (6, "UNode".into()), (10, "UNode".into()), (14, "UNode".into()),
            (3, "bool".into()), (4, "bool".into()), (7, "bool".into()), (11, "bool".into())]);
        let fold = |keep: &HashSet<i32>| super::inline_call_argument_temporaries(body, &refs, &locals, None, true,
            &HashMap::new(), &HashSet::new(), &HashSet::new(), &HashSet::new(), &HashSet::new(),
            &HashSet::new(), &HashSet::new(), &HashSet::new(), keep, &HashMap::new(), &HashSet::new(), &HashSet::new());
        let kept = fold(&spilled);
        for slot in [3, 4, 7, 11] {
            assert!(kept.contains(&format!("local_{slot} = ((Cast<UNode>(Actor)) != nullptr);")), "{kept}");
            assert!(kept.contains(&format!("if (local_{slot})")), "{kept}");
        }
        assert_eq!(super::fold_condition_temporaries(&kept, &locals, &refs, None, &spilled, &HashSet::new(), false), kept);
        let previous = fold(&HashSet::from([3]));
        assert!(previous.contains("local_3 ="), "{previous}");
        for slot in [4, 7, 11] { assert!(!previous.contains(&format!("local_{slot} =")), "{previous}"); }
        let mut true_return = f.clone(); let code = disassemble(&f.bytecode).unwrap();
        true_return.bytecode[code[5].offset_dw + 1] = 1;
        assert_eq!(super::spilled_boolean_names(&true_return, &refs), spilled);
    }

    #[test]
    fn reused_nullguard_rejects_nonterminal_nonliteral_or_open_earlier_lives() {
        let f = nullguard_after_literal_return_fixture();
        let refs = RefResolver::from_test_parameter_field_comparison(DataType::default(), false);
        let code = disassemble(&f.bytecode).unwrap();
        for fault in 0..10 {
            let mut other = f.clone();
            match fault {
                0 => other.bytecode[code[5].offset_dw + 1] = 2,
                1 => other.bytecode[code[6].offset_dw] ^= 1 << 16,
                2 => other.bytecode[code[7].offset_dw + 1] = code[8].offset_dw as i32 - code[7].offset_dw as i32 - 2,
                3 => other.bytecode[code[4].offset_dw + 1] = code[6].offset_dw as i32 - code[4].offset_dw as i32 - 2,
                4 => other.bytecode[code[4].offset_dw + 1] = code[7].offset_dw as i32 - code[4].offset_dw as i32 - 2,
                5 => other.bytecode.extend(function(&[("PshV4", &[4])]).bytecode),
                6 => other.bytecode.extend(function(&[("SetV1", &[4]), ("CpyVtoR4", &[4]), ("RET", &[2])]).bytecode),
                7 => other.obj_locals.retain(|(s, _)| *s != 6),
                8 => other.obj_locals.push((6, 2)),
                _ => other.ret.token = 0x44,
            }
            assert!(!super::spilled_boolean_names(&other, &refs).contains(&4), "fault {fault}");
        }
    }

    #[test]
    fn parameter_field_read_copy_keeps_its_typed_single_life_before_this_store() {
        let refs = RefResolver::from_test_parameter_field_comparison(DataType::default(), false);
        let mut f = function(&[("PshVPtr", &[(-2i16) as u16]), ("RefCpyV", &[2]),
            ("PshVPtr", &[2]), ("ADDSi", &[0]), ("RDSPtr", &[]), ("PshVPtr", &[0]),
            ("ADDSi", &[0]), ("REFCPY", &[]), ("PopPtr", &[]), ("RET", &[4])]);
        f.ret.token = 0x52;
        f.params.push(crate::cache::model::Param { name: "Holder".into(), flags: 0,
            ty: DataType { token: 5, type_info: 1, is_object_handle: true, ..Default::default() } });
        f.obj_locals = vec![(2, 1)];
        for ins in disassemble(&f.bytecode).unwrap() {
            if ins.op.name == "ADDSi" { f.bytecode[ins.offset_dw + 1] = 1; }
        }
        let keep = super::parameter_field_read_store_copies(&f, &refs, true);
        assert_eq!(keep, HashSet::from([2]));
        let body = "    local_2 = Holder;\n    this.Target = local_2.Target;\n";
        let locals = BTreeMap::from([(2, "UHolder".into())]);
        let roots = HashMap::from([("Holder".into(), "UHolder".into())]);
        assert_eq!(super::fold_member_read_temporaries(body, &HashSet::new(), &HashSet::new(),
            &locals, None, &roots, &refs, &HashMap::new(), false, &keep,
            &HashSet::new(), &HashMap::new()), body);
        for fault in 0..5 {
            let mut other = f.clone();
            match fault {
                0 => other.params[0].ty.is_object_const = true,
                1 => other.obj_locals.clear(),
                2 => other.obj_locals[0].1 = 2,
                3 => other.bytecode.extend(function(&[("PshVPtr", &[2])]).bytecode),
                _ => other.ret.token = 0x41,
            }
            assert!(super::parameter_field_read_store_copies(&other, &refs, true).is_empty(), "{fault}");
        }
        assert!(super::parameter_field_read_store_copies(&f,
            &RefResolver::from_test_parameter_field_comparison(DataType::default(), true), true).is_empty());
        assert!(super::parameter_field_read_store_copies(&f, &refs, false).is_empty());
    }

    #[test]
    fn inlined_cast_cleanup_requires_a_single_unnamed_typed_cast_life() {
        let refs = RefResolver::from_test_inlined_cast_cleanup(true);
        let mut f = function(&[("TYPEID", &[]), ("PSF", &[4]), ("PshVPtr", &[(-2i16) as u16]),
            ("CALLSYS", &[]), ("PshVPtr", &[4]), ("PshVPtr", &[0]), ("CALLINTF", &[]),
            ("CpyRtoV4", &[5]), ("FreeNullV8", &[4]), ("NOT", &[5]),
            ("CpyVtoV4", &[1, 5]), ("CpyVtoR4", &[1]), ("RET", &[4])]);
        f.ret.token = 0x41; f.obj_locals = vec![(4, 1)];
        let code = disassemble(&f.bytecode).unwrap();
        f.bytecode[code[0].offset_dw + 1] = 0x4000_0001;
        f.bytecode[code[3].offset_dw + 1] = 1;
        f.bytecode[code[6].offset_dw + 1] = 2;
        let body = "    local_5 = this.Check(Cast<UNode>(Actor));\n    local_4 = nullptr;\n    local_5 = !local_5;\n    local_1 = local_5;\n    return local_1;\n";
        let out = super::fold_inlined_cast_bool_cleanup(body, &f, &refs, &HashSet::new());
        assert!(!out.contains("local_4"), "{out}");
        assert!(out.contains("local_5 = !(this.Check(Cast<UNode>(Actor)));"), "{out}");
        for extra in [("RefCpyV", &[4][..]), ("FreeNullV8", &[4][..]), ("PSF", &[4][..])] {
            let mut other=f.clone(); other.bytecode.extend(function(&[extra]).bytecode);
            assert_eq!(super::fold_inlined_cast_bool_cleanup(body, &other, &refs, &HashSet::new()), body);
        }
        let other = format!("    Use(local_4);\n{body}");
        assert_eq!(super::fold_inlined_cast_bool_cleanup(&other, &f, &refs, &HashSet::new()), other);
        assert_eq!(super::fold_inlined_cast_bool_cleanup(body, &f,
            &RefResolver::from_test_inlined_cast_cleanup(false), &HashSet::new()), body);
        let mut other=f.clone(); other.obj_locals = vec![(4, 2)];
        assert_eq!(super::fold_inlined_cast_bool_cleanup(body, &other, &refs, &HashSet::new()), body);
    }

    fn assignment_order_fixture(ops: &[(&str, &[u16])], first_call: i32) -> Func {
        let mut f = function(ops);
        f.params.push(crate::cache::model::Param {
            name: "Key".into(), flags: 0,
            ty: DataType { token: 5, type_info: 1, is_reference: true, ..Default::default() },
        });
        let instrs = super::disassemble(&f.bytecode).unwrap();
        let mut first = true;
        for ins in instrs {
            if matches!(ins.op.name, "CALLSYS" | "CALL" | "CALLINTF") {
                f.bytecode[ins.offset_dw + 1] = if first { first_call } else { 3 };
                first = false;
            }
        }
        f
    }

    #[test]
    fn native_receiver_precedes_the_literal_field_write_without_later_receiver_refolding() {
        let code: Vec<(&str, &[u16])> = vec![
            ("CALLSYS", &[]), ("STOREOBJ", &[2]), ("SetV1", &[5]),
            ("LoadRObjR", &[2, 0]), ("WRTV1", &[5]), ("RET", &[2]),
        ];
        let refs = RefResolver::from_test_assignment_order_calls();
        let f = assignment_order_fixture(&code, 1);
        assert_eq!(super::assignment_call_order_slots(&f, &refs, true), HashSet::from([2]));
        let consumed = super::immediately_consumed_defs(&f);
        assert!(!consumed.iter().any(|(slot, _)| *slot == 2));
        let body = "UStorage local_2 = MakeStorage();\nlocal_2.Enabled = false;\n";
        assert_eq!(super::fold_assignment_receivers(body, &consumed), body);
        for (at, replacement) in [
            (0, ("CALL", &[][..])), (2, ("SetV4", &[5][..])),
            (3, ("LoadRObjR", &[4, 0][..])), (4, ("WRTV1", &[6][..])),
        ] {
            let mut other = code.clone(); other[at] = replacement;
            assert!(super::assignment_call_order_slots(&assignment_order_fixture(&other, 1), &refs, true).is_empty());
        }
        for extra in [("STOREOBJ", &[2][..]), ("SetV1", &[5][..]), ("PshVPtr", &[2][..])] {
            let mut other = code.clone(); other.push(extra);
            assert!(super::assignment_call_order_slots(&assignment_order_fixture(&other, 1), &refs, true).is_empty());
        }
        let mut interrupted = code.clone(); interrupted.insert(2, ("CALLSYS", &[]));
        assert!(super::assignment_call_order_slots(&assignment_order_fixture(&interrupted, 1), &refs, true).is_empty());
        assert!(super::assignment_call_order_slots(&assignment_order_fixture(&code, 2), &refs, true).is_empty());
    }

    #[test]
    fn native_double_rhs_precedes_the_addressed_default_argument_and_reference_write() {
        let code: Vec<(&str, &[u16])> = vec![
            ("CALLSYS", &[]), ("CpyRtoV8", &[6]), ("SetV8", &[4]), ("PSF", &[4]),
            ("PshVPtr", &[(-2i16) as u16]), ("PshVPtr", &[0]), ("ADDSi", &[0]),
            ("CALLSYS", &[]), ("WRTV8", &[6]), ("RET", &[4]),
        ];
        let refs = RefResolver::from_test_assignment_order_calls();
        let f = assignment_order_fixture(&code, 2);
        assert_eq!(super::assignment_call_order_slots(&f, &refs, true), HashSet::from([6]));
        assert!(super::assignment_call_order_slots(&f, &refs, false).is_empty());
        assert!(super::assignment_call_order_slots(&assignment_order_fixture(&code, 1), &refs, true).is_empty());
        for (at, replacement) in [
            (0, ("CALL", &[][..])), (3, ("PshV8", &[4][..])),
            (4, ("PshVPtr", &[0][..])), (4, ("PshVPtr", &[(-3i16) as u16][..])),
            (5, ("PshVPtr", &[2][..])), (7, ("CALL", &[][..])), (8, ("WRTV8", &[4][..])),
        ] {
            let mut other = code.clone(); other[at] = replacement;
            assert!(super::assignment_call_order_slots(&assignment_order_fixture(&other, 2), &refs, true).is_empty());
        }
        for extra in [("CpyRtoV8", &[6][..]), ("SetV8", &[4][..]), ("PshV8", &[6][..])] {
            let mut other = code.clone(); other.push(extra);
            assert!(super::assignment_call_order_slots(&assignment_order_fixture(&other, 2), &refs, true).is_empty());
        }
        let mut interrupted = code.clone(); interrupted.insert(4, ("CALLSYS", &[]));
        assert!(super::assignment_call_order_slots(&assignment_order_fixture(&interrupted, 2), &refs, true).is_empty());
        let mut by_value = f.clone();
        let call = super::disassemble(&by_value.bytecode).unwrap()[7].offset_dw;
        by_value.bytecode[call + 1] = 2;
        assert!(super::assignment_call_order_slots(&by_value, &refs, true).is_empty());
        let mut rvo = f; rvo.ret = DataType { token: 5, type_info: 1, ..Default::default() };
        assert!(super::assignment_call_order_slots(&rvo, &refs, true).is_empty());
    }

