    #[test]
    fn a_guard_and_cast_do_not_name_the_final_getter_argument_life() {
        let refs = RefResolver::from_test_reused_guard_cast_getter(0); let f = reused_guard_cast_getter_fixture();
        let check = |f: &Func, refs: &RefResolver| super::reused_guard_cast_getter_slots(f, refs, true);
        let allowed = check(&f, &refs); assert_eq!(allowed, HashSet::from([2]));
        let aliases = super::handle_alias_slots(&f); assert!(aliases.contains(&2));
        let body = "local_2 = this.Target;\nif (local_2 == nullptr)\n{\n    return;\n}\nlocal_2 = this.Target();\nthis.Bridge = Cast<ABridge>(local_2);\nlocal_2 = this.Avatar();\nthis.Handle = Attach(local_2, Tag, this, n\"Done\");\nreturn;\n";
        let locals = BTreeMap::from([(2, "AActor".into())]);
        let fold = |aliases: &HashSet<i32>| super::inline_call_argument_temporaries(body, &refs, &locals, None, true,
            &HashMap::new(), &HashSet::new(), &HashSet::new(), &HashSet::new(), &HashSet::new(), aliases,
            &HashSet::new(), &HashSet::new(), &HashSet::new(), &HashMap::new(), &HashSet::new(), &HashSet::new());
        assert!(fold(&aliases).contains("Attach(local_2,"));
        assert!(fold(&aliases.difference(&allowed).copied().collect()).contains("Attach(this.Avatar(),"));
        for fault in 1..=4 { assert!(check(&f, &RefResolver::from_test_reused_guard_cast_getter(fault)).is_empty(), "metadata {fault}"); }
        assert!(super::reused_guard_cast_getter_slots(&f, &refs, false).is_empty());
        let c = disassemble(&f.bytecode).unwrap();
        let mut wrong = f.clone(); wrong.bytecode[c[32].offset_dw] = (wrong.bytecode[c[32].offset_dw]&0xffff)|(12<<16); assert!(check(&wrong, &refs).is_empty());
        let mut jump = f.clone(); jump.bytecode[c[8].offset_dw+1] = c[32].offset_dw as i32-c[8].offset_dw as i32-2; assert!(check(&jump, &refs).is_empty());
        let mut duplicate = f.clone(); duplicate.obj_locals.push((2,7)); assert!(check(&duplicate, &refs).is_empty());
        let mut foreign = f.clone(); foreign.obj_locals[0].1 = 8; assert!(check(&foreign, &refs).is_empty());
        let mut extra = f.clone(); extra.bytecode.extend(function(&[("PshVPtr", &[2])]).bytecode); assert!(check(&extra, &refs).is_empty());
    }

    #[test]
    fn a_field_null_guard_does_not_name_the_later_argument_and_receiver_getters() {
        let refs = RefResolver::from_test_reused_null_guard_getters(0);
        assert!(refs.arg_position_accepts_temporary("Remove", 3, 1));
        assert!(!refs.arg_position_accepts_temporary("UnknownRemove", 3, 1));
        let f = reused_null_guard_getter_fixture();
        let allowed = super::reused_null_guard_getter_slots(&f, &refs);
        assert_eq!(allowed, HashSet::from([4]));
        let aliased = super::handle_alias_slots(&f);
        assert_eq!(aliased, HashSet::from([4]));
        let body = "if (this.Controlled != nullptr)\n{\n    local_4 = this.GetComponent();\n    this.Controlled.Remove(this.TargetEffect, local_4, -1);\n}\nlocal_8 = this.GetComponent();\nlocal_4 = this.GetComponent();\nlocal_4.Remove(this.CasterEffect, local_8, -1);\nreturn;\n";
        let locals = BTreeMap::from([(4, "UComponent".into()), (8, "UComponent".into())]);
        let fold = |aliases: &HashSet<i32>| super::inline_call_argument_temporaries(body, &refs, &locals, None, true,
            &HashMap::new(), &HashSet::new(), &HashSet::new(), &HashSet::new(), &HashSet::new(), aliases,
            &HashSet::new(), &HashSet::new(), &HashSet::new(), &HashMap::new(), &HashSet::new(), &HashSet::new());
        assert!(fold(&aliased).contains("local_4 = this.GetComponent();"));
        let folded = fold(&aliased.difference(&allowed).copied().collect());
        assert!(!folded.contains("local_4"), "{folded}");
        assert!(!folded.contains("local_8"), "{folded}");
        assert!(folded.contains("this.Controlled.Remove(this.TargetEffect, this.GetComponent(), -1);"), "{folded}");
        assert!(folded.contains("this.GetComponent().Remove(this.CasterEffect, this.GetComponent(), -1);"), "{folded}");
        for fault in 1..=5 {
            assert!(super::reused_null_guard_getter_slots(&f, &RefResolver::from_test_reused_null_guard_getters(fault)).is_empty(), "metadata {fault}");
        }
        let code = disassemble(&f.bytecode).unwrap();
        let mut wrong = f.clone(); wrong.bytecode[code[25].offset_dw + 1] = 12;
        assert!(super::reused_null_guard_getter_slots(&wrong, &refs).is_empty());
        let mut extra = function(&[("PshVPtr", &[4])]); extra.bytecode.extend(f.bytecode.clone());
        extra.ret = f.ret.clone(); extra.obj_locals = f.obj_locals.clone();
        assert!(super::reused_null_guard_getter_slots(&extra, &refs).is_empty());
        let mut entered = function(&[("JMP", &[])]); entered.bytecode[1] = code[9].offset_dw as i32;
        entered.bytecode.extend(f.bytecode.clone()); entered.ret = f.ret.clone(); entered.obj_locals = f.obj_locals.clone();
        assert!(super::reused_null_guard_getter_slots(&entered, &refs).is_empty());
    }

    #[test]
    fn a_value_member_read_after_argument_pushes_keeps_its_producer_statement() {
        let refs = RefResolver::from_test_member_result_before_arguments(0);
        let mut f = function(&[("PSF", &[18]), ("PshVPtr", &[0]), ("CALLINTF", &[]), ("PshNull", &[]),
            ("SetV1", &[23]), ("PshV4", &[23]), ("PshGPtr", &[]), ("PshGPtr", &[]),
            ("LoadVObjR", &[18, 0]), ("RDR8", &[8]), ("PshV8", &[8]), ("RET", &[2])]);
        f.obj_locals = vec![(18, 1)];
        let code = disassemble(&f.bytecode).unwrap();
        f.bytecode[code[2].offset_dw + 1] = 10;
        f.bytecode[code[8].offset_dw + 2] = 1;
        let check = |f: &Func, refs: &RefResolver| super::member_results_before_argument_pushes(f, refs);
        assert_eq!(check(&f, &refs), HashSet::from([18]));
        let source = "FPoint local_18 = this.Floor();\nfloat local_8 = local_18.Z;\nUse(local_8);\n";
        let inline = |keep: &HashSet<i32>| super::inline_unnamed_value_temporaries(source, &HashSet::from([(18, 1)]),
            &HashSet::new(), &HashSet::new(), &refs, &HashSet::new(), keep, &HashMap::new(),
            &HashSet::new(), &HashSet::new(), &HashSet::new(), &HashSet::new());
        assert_eq!(inline(&check(&f, &refs)), source);
        assert_ne!(inline(&HashSet::new()), source);
        for fault in 1..=6 {
            assert!(check(&f, &RefResolver::from_test_member_result_before_arguments(fault)).is_empty(), "metadata {fault}");
        }
        for (at, word, value) in [(1, 0, 2), (4, 1, 1), (8, 2, 2), (10, 0, 9)] {
            let mut wrong = f.clone();
            let pos = code[at].offset_dw + word;
            if word == 0 { wrong.bytecode[pos] = (wrong.bytecode[pos] & 0xffff) | (value << 16); }
            else { wrong.bytecode[pos] = value; }
            assert!(check(&wrong, &refs).is_empty(), "operand {at}/{word}");
        }
        let mut wrong = f.clone(); wrong.obj_locals[0].1 = 2; assert!(check(&wrong, &refs).is_empty());
        let mut extra = f.clone(); extra.bytecode.extend(function(&[("PSF", &[18])]).bytecode); assert!(check(&extra, &refs).is_empty());
        let mut jump = f.clone(); jump.bytecode.splice(0..0, function(&[("JMP", &[])]).bytecode); assert!(check(&jump, &refs).is_empty());
    }

