    #[test]
    fn changed_bool_fields_restore_short_circuit_reads_and_all_saved_values() {
        let f = changed_bool_fields_fixture();
        let refs = RefResolver::from_test_changed_bool_fields();
        let fields = ["A","LastA","B","LastB","C","LastC","Settled"].into_iter()
            .map(|n| (n.to_owned(), "bool".to_owned())).collect::<HashMap<_,_>>();
        let fold = |f: &Func, fields: &HashMap<String,String>| super::fold_changed_bool_fields("    old;\n", f, &refs, Some(fields), true);
        assert_eq!(fold(&f, &fields), concat!(
            "    if ((this.A != this.LastA) || (this.B != this.LastB) || (this.C != this.LastC))\n",
            "    {\n        this.Settled = false;\n    }\n",
            "    this.LastA = this.A;\n    this.LastB = this.B;\n    this.LastC = this.C;\n    return;\n"));
        let code = disassemble(&f.bytecode).unwrap();
        // Every changed successor, comparison/copy/store operand, field owner,
        // normalization opcode, and bool literal must reject the whole rewrite.
        for at in [7,9,21,23,35,8,22,36] {
            let mut other = f.clone(); other.bytecode[code[at].offset_dw+1] ^= 1;
            assert_eq!(fold(&other,&fields),"    old;\n", "immediate {at}");
        }
        for (at,n) in [(6,0),(6,1),(16,1),(19,0),(19,1),(30,0),(33,1),(34,0),(38,0),(42,0),(51,0)] {
            let mut other = f.clone();
            let shift = if n == 0 { 16 } else { 0 };
            other.bytecode[code[at].offset_dw+usize::from(n>0)] ^= 1 << shift;
            assert_eq!(fold(&other,&fields),"    old;\n", "operand {at}/{n}");
        }
        for at in [0,3,10,13,24,27,37,39,41,43,45,47,49] {
            let mut other = f.clone(); other.bytecode[code[at].offset_dw+1] = 2;
            assert_eq!(fold(&other,&fields),"    old;\n", "owner {at}");
        }
        let mut wrong_update = f.clone(); wrong_update.bytecode[code[41].offset_dw] ^= 1 << 16;
        assert_eq!(fold(&wrong_update,&fields),"    old;\n");
        let mut negation = f.clone(); negation.bytecode[code[2].offset_dw] = function(&[("NEGf",&[1])]).bytecode[0];
        assert_eq!(fold(&negation,&fields),"    old;\n");
        let mut extra = f.clone(); extra.bytecode.extend(function(&[("CALL", &[])]).bytecode);
        assert_eq!(fold(&extra,&fields),"    old;\n");
        for name in fields.keys() {
            let mut other = fields.clone(); other.insert(name.clone(),"int".into());
            assert_eq!(fold(&f,&other),"    old;\n");
        }
        assert_eq!(super::fold_changed_bool_fields("old;",&f,&refs,Some(&fields),false),"old;");
        let mut other = f.clone(); other.ret.token=0x44; assert_eq!(fold(&other,&fields),"    old;\n");
        let mut other = f.clone(); other.obj_locals.push((1,1)); assert_eq!(fold(&other,&fields),"    old;\n");
    }

    fn eager_bool_diamond(negated: bool) -> Func {
        let mut ops: Vec<(&str, &[u16])> = vec![
            ("CALL", &[]), ("CpyRtoV4", &[6]), ("CALL", &[]), ("CpyRtoV4", &[9]),
            ("CpyVtoR1", &[9]), (if negated { "JLowNZ" } else { "JLowZ" }, &[]),
            (if negated { "SetV4" } else { "SetV1" }, &[11]), ("JMP", &[]),
            ("CpyVtoV4", if negated { &[10, 6] } else { &[11, 6] }),
        ];
        if negated { ops.extend([("NOT", &[10][..]), ("CpyVtoV4", &[11, 10][..])]); }
        ops.extend([("CpyVtoR4", &[11][..]), ("RET", &[0][..])]);
        let mut f = function(&ops);
        let code = super::disassemble(&f.bytecode).unwrap();
        f.bytecode[code[0].offset_dw + 1] = 101;
        f.bytecode[code[2].offset_dw + 1] = 102;
        f.bytecode[code[6].offset_dw + 1] = i32::from(!negated);
        f.bytecode[code[5].offset_dw + 1] = code[8].offset_dw as i32 - code[5].offset_dw as i32 - 2;
        let after = if negated { 11 } else { 9 };
        f.bytecode[code[7].offset_dw + 1] = code[after].offset_dw as i32 - code[7].offset_dw as i32 - 2;
        f
    }

    #[test]
    fn eager_bool_calls_remain_named_before_direct_or_and_negated_and_arms() {
        let refs = RefResolver::from_test_eager_bool_calls(0x41);
        for negated in [false, true] {
            let f = eager_bool_diamond(negated);
            let sites = super::named_value_sites(&f, &refs);
            assert!(sites.contains(&(6, "Saved".to_owned())));
            let body = if negated {
                "local_6 = Saved();\nlocal_9 = Other();\nlocal_11 = local_9 && !(local_6);\nreturn local_11;\n"
            } else {
                "local_6 = Saved();\nlocal_9 = Other();\nlocal_11 = local_9 || local_6;\nreturn local_11;\n"
            };
            let locals = std::collections::BTreeMap::from([(6, "bool".into()), (9, "bool".into()), (11, "bool".into())]);
            let call_types = HashMap::from([(6, "bool".into()), (9, "bool".into())]);
            let empty = HashSet::new();
            let folded = super::inline_call_argument_temporaries(body, &refs, &locals, None, true,
                &call_types, &empty, &empty, &empty, &empty, &empty, &empty, &empty, &empty,
                &HashMap::new(), &empty, &sites);
            assert!(folded.contains("local_6 = Saved();"), "{folded}");
            assert!(!folded.contains("|| Saved()") && !folded.contains("!(Saved())"), "{folded}");
        }
    }

    #[test]
    fn eager_bool_witness_rejects_ambiguous_lives_wrong_types_and_non_diamonds() {
        let refs = RefResolver::from_test_eager_bool_calls(0x41);
        let f = eager_bool_diamond(false);
        let site = (6, "Saved".to_owned());
        let mut repeated = f.clone();
        let mut extra = function(&[("CALL", &[]), ("CpyRtoV4", &[6])]);
        extra.bytecode[1] = 101;
        repeated.bytecode.extend(extra.bytecode);
        assert!(!super::named_value_sites(&repeated, &refs).contains(&site));
        let mut separate = f.clone();
        let mut extra = function(&[("CALL", &[]), ("CpyRtoV4", &[20])]);
        extra.bytecode[1] = 101;
        separate.bytecode.extend(extra.bytecode);
        assert!(super::named_value_sites(&separate, &refs).contains(&site));
        assert!(!super::named_value_sites(&f, &RefResolver::from_test_eager_bool_calls(0x44)).contains(&site));
        for changed in [5, 6, 7] {
            let mut other = f.clone();
            let at = super::disassemble(&other.bytecode).unwrap()[changed].offset_dw;
            other.bytecode[at + 1] += 1; // wrong branch target / noncanonical literal / wrong join
            assert!(!super::named_value_sites(&other, &refs).contains(&site));
        }
        for op in ["SetV1", "PshV4"] {
            let mut other = f.clone();
            // Place the extra mention before the diamond. All relative diamond
            // offsets remain unchanged because both their source and target shift.
            let at = super::disassemble(&other.bytecode).unwrap()[4].offset_dw;
            other.bytecode.splice(at..at, function(&[(op, &[6])]).bytecode);
            assert!(!super::named_value_sites(&other, &refs).contains(&site));
        }
        let mut conditional = function(&[
            ("CpyVtoR1", &[9]), ("JLowZ", &[]), ("SetV1", &[11]), ("JMP", &[]),
            ("CALL", &[]), ("CpyRtoV4", &[6]), ("CpyVtoV4", &[11, 6]),
            ("CpyVtoR4", &[11]), ("RET", &[0]),
        ]);
        let code = super::disassemble(&conditional.bytecode).unwrap();
        conditional.bytecode[code[1].offset_dw + 1] = code[4].offset_dw as i32 - code[1].offset_dw as i32 - 2;
        conditional.bytecode[code[2].offset_dw + 1] = 1;
        conditional.bytecode[code[3].offset_dw + 1] = code[7].offset_dw as i32 - code[3].offset_dw as i32 - 2;
        conditional.bytecode[code[4].offset_dw + 1] = 101;
        assert!(!super::named_value_sites(&conditional, &refs).contains(&site));
        // A prior unrelated physical-slot life is permitted, but does not inherit
        // the Saved call's witness: its own callee differs.
        let mut prior = function(&[("CALL", &[]), ("CpyRtoV4", &[6]), ("CpyVtoV4", &[20, 6])]);
        prior.bytecode[1] = 102;
        prior.bytecode.extend(f.bytecode);
        let sites = super::named_value_sites(&prior, &refs);
        assert!(sites.contains(&site));
        assert!(!sites.contains(&(6, "Other".to_owned())));
    }

    #[test]
    fn constructor_parameter_defaults_are_not_parameter_names() {
        assert_eq!(super::signature_parameters(
            "    Example(const TSubclassOf<UState> &inout State = nullptr, const bool Enabled = false, const FGameplayTag &inout Tag = FGameplayTag(), const float Distance = 500.f)"),
            vec!["State", "Enabled", "Tag", "Distance"]);
        let fields = HashSet::from(["State", "Enabled"]);
        let mut constructors = "    Example()\n    {\n        this.State = nullptr;\n        this.Enabled = false;\n        return;\n    }\n    Example(UState state = nullptr, const bool enabled = false)\n    {\n        this.State = nullptr;\n        this.Enabled = false;\n        this.State = state;\n        this.Enabled = enabled;\n        return;\n    }\n".to_owned();
        assert_eq!(super::extract_member_initializers(&mut constructors, &fields),
            HashMap::from([("State".into(), "nullptr".into()), ("Enabled".into(), "false".into())]));
        assert!(!constructors.contains("this.State = nullptr;") && !constructors.contains("this.Enabled = false;"));
        assert!(constructors.contains("this.State = state;") && constructors.contains("this.Enabled = enabled;"));
    }

    #[test]
    fn defaulted_parameter_values_still_cannot_be_lifted_into_field_declarations() {
        // Recover the actual parameter name even when a default follows it.
        // Otherwise this store appears parameter-independent and leaves scope.
        let original = "    Example(UState state = nullptr)\n    {\n        this.State = state;\n        return;\n    }\n";
        let mut constructors = original.to_owned();
        assert!(super::extract_member_initializers(&mut constructors, &HashSet::from(["State"])).is_empty());
        assert_eq!(constructors, original);
    }

    #[test]
    fn member_initializers_require_the_common_constructor_prefix_and_keep_explicit_repeats() {
        let mut constructors = "    Example()\n    {\n        super();\n        this.Radius = 2000.0;\n        this.Radius = 2000.0;\n        this.Night = MakeState();\n        this.Day = MakeState();\n        return;\n    }\n    Example(float radius, UState night, UState day)\n    {\n        super();\n        this.Radius = 2000.0;\n        this.Radius = radius;\n        this.Night = night;\n        this.Day = day;\n        return;\n    }\n".to_owned();
        let fields = HashSet::from(["Radius", "Night", "Day"]);
        let initializers = super::extract_member_initializers(&mut constructors, &fields);
        assert_eq!(initializers, HashMap::from([("Radius".to_owned(), "2000.0".to_owned())]));
        assert_eq!(constructors.matches("this.Radius = 2000.0;").count(), 1);
        assert_eq!(constructors.matches("MakeState()").count(), 2);
        assert!(constructors.contains("this.Radius = radius;"));
        assert!(constructors.contains("this.Night = night;"));
        assert!(constructors.contains("this.Day = day;"));
    }

    #[test]
    fn member_initializers_keep_conflicting_values_repeated_calls_and_nested_stores() {
        let fields = HashSet::from(["Value"]);
        let original = "    Example()\n    {\n        this.Value = 1;\n        return;\n    }\n    Example(bool enabled)\n    {\n        this.Value = 2;\n        return;\n    }\n";
        let mut constructors = original.to_owned();
        assert!(super::extract_member_initializers(&mut constructors, &fields).is_empty());
        assert_eq!(constructors, original);
        let mut repeated = "    Example()\n    {\n        this.Value = MakeValue();\n        this.Value = MakeValue();\n        return;\n    }\n    Example(bool enabled)\n    {\n        this.Value = MakeValue();\n        if (enabled)\n        {\n            this.Value = MakeValue();\n        }\n        return;\n    }\n".to_owned();
        assert_eq!(super::extract_member_initializers(&mut repeated, &fields),
            HashMap::from([("Value".to_owned(), "MakeValue()".to_owned())]));
        // One call moves to each constructor's field initializer; the explicit
        // second call and the conditional call must remain in their original bodies.
        assert_eq!(repeated.matches("MakeValue()").count(), 2);
        assert!(repeated.contains("if (enabled)\n        {\n            this.Value = MakeValue();\n        }"));
    }


    #[test]
    fn lvalue_conditional_copy_is_not_evidence_of_a_preexisting_destination() {
        let mut f = function(&[("CMPIi", &[7]), ("JZ", &[]), ("LDV", &[7]),
            ("JMP", &[]), ("LDV", &[8]), ("RDR4", &[19]), ("CpyVtoV4", &[11, 19]),
            ("RET", &[0])]);
        let code = super::disassemble(&f.bytecode).unwrap();
        for (jump, target) in [(1,4), (3,5)] {
            f.bytecode[code[jump].offset_dw + 1] = code[target].offset_dw as i32
                - code[jump].offset_dw as i32 - 2;
        }
        assert!(super::slots_with_assignment_writes(&f).is_empty());
        let body = "if (ready)\n{\n    local_11 = Count();\n    local_11 = local_11 - 1;\n    Use(local_11);\n    return true;\n}\nlocal_11 = (test != -1 ? a : b);\nUse(local_11);\nreturn true;\n";
        let (out, suppressed) = super::rewrite_primitive_lives_decl_init(body,
            &std::collections::BTreeMap::from([(11, "int".into())]), &RefResolver::default(),
            &HashSet::new(), &super::slots_with_assignment_writes(&f), &HashMap::new(), &HashMap::new(), &HashSet::new());
        assert!(suppressed.contains(&11));
        assert!(out.contains("int local_11 = Count();") && out.contains("int local_11_2 = (test"), "{out}");
        f.bytecode[code[3].offset_dw + 1] += 1;
        assert_eq!(super::slots_with_assignment_writes(&f), HashSet::from([11]));
    }


    fn default_return_conditional_fixture() -> Func {
        let mut f = function(&[
            ("PshVPtr", &[65532]), ("CALLSYS", &[]), ("STOREOBJ", &[2]), ("CmpPtrNull", &[2]), ("JZ", &[]),
            ("PshVPtr", &[0]), ("CALLSYS", &[]), ("SetV8", &[6]), ("CMPd", &[65530, 6]), ("JNS", &[]),
            ("PshVPtr", &[65532]), ("CALLSYS", &[]), ("STOREOBJ", &[2]), ("PshVPtr", &[2]), ("CALLSYS", &[]),
            ("CpyRtoV4", &[7]), ("MULIf", &[7, 7]), ("fTOd", &[6, 7]), ("CpyVtoV8", &[10, 6]), ("JMP", &[]),
            ("CpyVtoV8", &[10, 65530]), ("PshV8", &[10]), ("PshVPtr", &[65532]), ("CALLSYS", &[]), ("STOREOBJ", &[2]),
            ("PshVPtr", &[2]), ("PshVPtr", &[65534]), ("PSF", &[18]), ("CALL", &[]), ("PSF", &[18]),
            ("PshVPtr", &[0]), ("CALLSYS", &[]), ("PSF", &[18]), ("CALLSYS", &[]), ("JMP", &[]),
            // The opposite branch reuses f32 scratch 7 and return scratch 18.
            ("PshVPtr", &[0]), ("CALLSYS", &[]), ("PshC4", &[]), ("SetV1", &[3]), ("PshV4", &[3]),
            ("dTOf", &[7, 65530]), ("PshV4", &[7]), ("PSF", &[24]), ("PshVPtr", &[65532]), ("CALLSYS", &[]),
            ("PSF", &[24]), ("PshVPtr", &[65534]), ("CALLSYS", &[]), ("STOREOBJ", &[26]), ("PshVPtr", &[26]),
            ("PSF", &[18]), ("CALLSYS", &[]), ("PSF", &[18]), ("PshVPtr", &[0]), ("CALLSYS", &[]),
            ("PSF", &[18]), ("CALLSYS", &[]), ("RET", &[8]),
        ]);
        let code = disassemble(&f.bytecode).unwrap();
        for (at, ptr) in [(1, 2), (6, 1), (11, 2), (14, 3), (23, 2), (28, 6), (31, 4), (33, 5),
            (36, 1), (44, 7), (47, 8), (51, 9), (54, 4), (56, 5)] { f.bytecode[code[at].offset_dw + 1] = ptr; }
        f.bytecode[code[16].offset_dw + 2] = 1.5f32.to_bits() as i32;
        f.bytecode[code[37].offset_dw + 1] = (-1.0f32).to_bits() as i32;
        for (at, target) in [(4, 35), (9, 20), (19, 21), (34, 57)] {
            f.bytecode[code[at].offset_dw + 1] = code[target].offset_dw as i32 - code[at].offset_dw as i32 - 2;
        }
        f.ret = DataType { token: 5, type_info: 100, ..Default::default() };
        f.params = [("AI", DataType { token: 5, type_info: 101, is_object_handle: true, ..Default::default() }),
            ("Other", DataType { token: 5, type_info: 102, is_object_handle: true, ..Default::default() }),
            ("Reach", DataType { token: 0x51, is_object_const: true, is_read_only: true, ..Default::default() })]
            .into_iter().map(|(name, ty)| super::super::model::Param { name: name.into(), ty, flags: 0 }).collect();
        f.obj_locals = vec![(2, 103), (18, 100), (24, 104), (26, 105)];
        f
    }

    fn default_return_conditional_body() -> &'static str {
        "    if (Other.Actor() != nullptr)\n    {\n        if (Reach < 0.0)\n        {\n            local_7 = Other.Actor().Radius();\n            local_7 = local_7 * 1.5f;\n            local_6 = local_7;\n            local_10 = local_6;\n        }\n        else\n        {\n            local_10 = Reach;\n        }\n        return Dispatch(AI, Other.Actor(), local_10);\n    }\n    else\n    {\n        return Fallback(AI, Other, float32(Reach));\n    }\n"
    }

    #[test]
    fn default_return_constructor_stays_before_the_widened_conditional_argument() {
        let f = default_return_conditional_fixture(); let refs = RefResolver::from_test_default_return_conditional(0);
        let body = default_return_conditional_body(); let locals = BTreeMap::from([(6, "float".into()), (7, "float32".into()), (10, "float".into())]);
        let folded = super::fold_conditional_values(body, &locals, &refs, None, None, &f);
        let expected = body.replace("        if (Reach < 0.0)\n        {\n            local_7 = Other.Actor().Radius();\n            local_7 = local_7 * 1.5f;\n            local_6 = local_7;\n            local_10 = local_6;\n        }\n        else\n        {\n            local_10 = Reach;\n        }\n        return Dispatch(AI, Other.Actor(), local_10);",
            "        return Dispatch(AI, Other.Actor(), Reach < 0.0 ? (Other.Actor().Radius() * 1.5f) : Reach);");
        assert_eq!(folded, expected);
        let collapsed = super::collapse_single_use_accumulators(&folded, &HashSet::new(), &locals, &HashSet::new());
        assert_eq!(collapsed, expected);
        let (declared, _) = super::rewrite_first_use_decl_init(&collapsed, &locals, &refs,
            &HashSet::new(), &HashMap::new(), &HashSet::new(), &HashSet::new(), &HashMap::new(), &HashSet::new(), &HashSet::new());
        assert_eq!(declared, expected);
        assert_eq!(super::fold_conditional_values(&declared, &locals, &refs, None, None, &f), declared);
    }

    #[test]
    fn default_return_conditional_requires_typed_frame_closed_text_and_jump_boundaries() {
        let f = default_return_conditional_fixture(); let body = default_return_conditional_body();
        for fault in 1..=11 {
            assert_eq!(super::fold_default_return_conditionals(body, &f, &RefResolver::from_test_default_return_conditional(fault)), body, "fault {fault}");
        }
        let refs = RefResolver::from_test_default_return_conditional(0);
        let code = disassemble(&f.bytecode).unwrap();
        for bad_at in [6, 17, 21, 31, 33] {
            let mut wrong = f.clone(); wrong.bytecode[code[bad_at].offset_dw] ^= 1;
            assert_eq!(super::fold_default_return_conditionals(body, &wrong, &refs), body, "opcode {bad_at}");
        }
        let mut entry = f.clone(); entry.bytecode[code[4].offset_dw + 1] = code[17].offset_dw as i32 - code[4].offset_dw as i32 - 2;
        assert_eq!(super::fold_default_return_conditionals(body, &entry, &refs), body);
        let mut wrong_slot = f.clone(); wrong_slot.obj_locals[0].1 = 104;
        assert_eq!(super::fold_default_return_conditionals(body, &wrong_slot, &refs), body);
        let mut wrong_param = f.clone(); wrong_param.params[2].ty.is_reference = true;
        assert_eq!(super::fold_default_return_conditionals(body, &wrong_param, &refs), body);
        for other in [body.replace("1.5f", "2.0f"), body.replace("return Dispatch(AI, Other.Actor(), local_10);", "return Dispatch(AI, Other.Actor(), local_10 + 1.0);"),
            body.replace("return Fallback", "Use(local_7);\n        return Fallback"), body.replace("local_10 = Reach;", "local_10 = OtherReach;")] {
            assert_eq!(super::fold_default_return_conditionals(&other, &f, &refs), other);
        }
    }

    #[test]
    fn a_member_copy_keeps_its_scope_lifetime_through_conversion_and_member_folding() {
        let refs = RefResolver::from_test_literal_string_scope(0);
        let mut f = function(&[("PSF", &[100]), ("CALLSYS", &[]),
            ("PSF", &[118]), ("CALLSYS", &[]), ("PSF", &[118]), ("CALLSYS", &[]),
            ("PSF", &[100]), ("CALLSYS", &[]), ("RET", &[0])]);
        let code = disassemble(&f.bytecode).unwrap();
        for (at, ptr) in [(1, 1), (3, 1), (5, 3), (7, 3)] {
            f.bytecode[code[at].offset_dw + 1] = ptr;
        }
        let scoped = |f: &Func| {
            let constructions = super::default_construction_counts(f, &refs);
            super::scope_exit_destroyed_slots(f, &refs).into_iter()
                .filter(|slot| constructions.get(slot) == Some(&1)).collect::<HashSet<_>>()
        };
        let keep = scoped(&f);
        assert_eq!(keep, HashSet::from([100, 118]));
        let locals = BTreeMap::from([(100, "FString".into())]);
        let fields = HashMap::from([("Label".into(), "FString".into())]);
        let source = "    FString local_100 = FString(this.Label);\n    Use(local_100);\n    Later();\n";
        let plain = super::drop_redundant_conversions(source, Some(&fields), &HashMap::new(), &refs,
            &HashSet::new(), &HashSet::new());
        assert_eq!(plain, source.replace("FString(this.Label)", "this.Label"));
        let fold = |body: &str, named: &HashSet<i32>| super::fold_member_read_temporaries(body,
            &HashSet::new(), &HashSet::new(), &locals, Some(&fields), &HashMap::new(), &refs,
            &HashMap::new(), false, named, &HashSet::new(), &HashMap::new());
        assert_eq!(fold(&plain, &keep), plain);
        assert_eq!(fold(&fold(&plain, &keep), &keep), plain);
        assert_eq!(fold(&plain, &HashSet::new()), "    Use(this.Label);\n    Later();\n");
        // A single expression cleanup does not acquire scope retention.
        let mut single = function(&[("PSF", &[100]), ("CALLSYS", &[]), ("RET", &[0])]);
        single.bytecode[1 + 1] = 3;
        let temporary = super::scope_exit_destroyed_slots(&single, &refs);
        assert!(temporary.is_empty());
        assert_eq!(fold(&plain, &temporary), fold(&plain, &HashSet::new()));
        // Two constructor/destructor lives are two expression temporaries,
        // not one local destroyed at two exits (e.g. short-circuit equality).
        let mut reused = function(&[("PSF", &[100]), ("CALLSYS", &[]),
            ("PSF", &[100]), ("CALLSYS", &[]), ("CpyVtoR1", &[5]),
            ("PSF", &[100]), ("CALLSYS", &[]), ("PSF", &[100]), ("CALLSYS", &[]),
            ("CpyVtoR1", &[6]), ("RET", &[0])]);
        let code = disassemble(&reused.bytecode).unwrap();
        for (at, ptr) in [(1, 1), (3, 3), (6, 1), (8, 3)] {
            reused.bytecode[code[at].offset_dw + 1] = ptr;
        }
        assert!(super::scope_exit_destroyed_slots(&reused, &refs).contains(&100));
        assert!(scoped(&reused).is_empty());
        assert_eq!(fold(&plain, &scoped(&reused)), fold(&plain, &HashSet::new()));
    }

    #[test]
    fn float_outref_keeps_its_width_when_converted_into_another_slot() {
        let check = |f: &Func, ty: Option<&str>| {
            let fc = super::FuncCode { func: "Initialize".into(), is_method: false,
                param_names: vec![], param_types: vec![], ret: f.ret.clone(), bytecode: f.bytecode.clone() };
            let outrefs = ty.map(|t| HashMap::from([(21, t.to_owned())])).unwrap_or_default();
            super::infer_float_flow(f, &fc, &RefResolver::default(), None, &HashMap::new(), &outrefs, &HashSet::new())
        };
        for cast in ["fTOi", "fTOu"] {
            let f = function(&[("RDR4", &[28]), ("iTOf", &[22, 28]), ("CpyVtoV4", &[21, 22]),
                (cast, &[28, 21]), ("WRTV4", &[28]), ("RET", &[])]);
            assert_eq!(check(&f, Some("float32")), HashMap::from([(21, super::NumKind::F32), (22, super::NumKind::F32)]));
            assert!(check(&f, None).is_empty());
            assert!(check(&f, Some("float")).is_empty());
            assert!(check(&f, Some("int")).is_empty());
            let mut conflict = f.clone(); conflict.bytecode.extend(function(&[("IncVi", &[21])]).bytecode);
            assert!(check(&conflict, Some("float32")).is_empty());
            let mut wide = f.clone(); wide.bytecode.extend(function(&[("CpyVtoV8", &[24, 21])]).bytecode);
            assert!(check(&wide, Some("float32")).is_empty());
            let in_place = function(&[("iTOf", &[22, 28]), ("CpyVtoV4", &[21, 22]), (cast, &[21, 21]), ("RET", &[])]);
            assert!(check(&in_place, Some("float32")).is_empty());
        }
    }

    fn widened_division_fixture() -> Func {
        let mut bytecode = Vec::new();
        for (field, result, denominator, output) in [(8u16, 17u16, 15u16, 12u16), (12, 21, 17, 20)] {
            let mut part = function(&[("LoadRObjR", &[6, field]), ("RDR4", &[13]), ("CMPIi", &[13]),
                ("JP", &[]), ("SetV4", &[result]), ("JMP", &[]), ("SetV4", &[16]),
                ("LoadRObjR", &[6, field]), ("RDR4", &[14]), ("SUBIi", &[14, 14]),
                ("iTOf", &[denominator, 14]), ("DIVf", &[result, 16, denominator]),
                ("fTOd", &[10, result]), ("CpyVtoV8", &[output, 10])]);
            let c = disassemble(&part.bytecode).unwrap();
            for at in [0, 7] { part.bytecode[c[at].offset_dw + 2] = 100; }
            part.bytecode[c[2].offset_dw + 1] = 1; part.bytecode[c[9].offset_dw + 2] = 1;
            for at in [4, 6] { part.bytecode[c[at].offset_dw + 1] = 1.0f32.to_bits() as i32; }
            for (at, to) in [(3, 6), (5, 12)] { part.bytecode[c[at].offset_dw + 1] = c[to].offset_dw as i32 - c[at].offset_dw as i32 - 2; }
            bytecode.extend(part.bytecode);
        }
        bytecode.extend(function(&[("MULd", &[10, 20, 12]), ("CpyVtoR8", &[10]), ("RET", &[0])]).bytecode);
        Func { bytecode, obj_locals: vec![(6, 100)], ..function(&[]) }
    }

    fn widened_division_body() -> String {
        let mut out = String::new();
        for (field, result, denominator, output) in [("MoveCount", 17, 15, 12), ("AttackCount", 21, 17, 20)] {
            out.push_str(&format!("    if (int(local_6.{field}) <= 1)\n    {{\n        local_{result} = 1.0f;\n    }}\n    else\n    {{\n        local_16 = 1.0f;\n        local_14 = int(local_6.{field});\n        local_14 = local_14 - 1;\n        local_{denominator} = local_14;\n        local_{result} = local_16 / local_{denominator};\n    }}\n    local_10 = local_{result};\n    local_{output} = local_10;\n"));
        }
        out.push_str("    return local_20 * local_12;\n"); out
    }

    #[test]
    fn widened_conditionals_recover_both_arms_before_shared_scratch_lives_split() {
        let f = widened_division_fixture(); let refs = RefResolver::from_test_widened_division_fields("int");
        let locals = BTreeMap::from([(12, "float".into()), (20, "float".into())]);
        let folded = super::fold_conditional_values(&widened_division_body(), &locals, &refs, None, None, &f);
        let (declared, _) = super::rewrite_first_use_decl_init(&folded, &locals, &refs,
            &HashSet::new(), &HashMap::new(), &HashSet::new(), &HashSet::new(), &HashMap::new(), &HashSet::new(), &HashSet::new());
        for (field, output) in [("MoveCount", 12), ("AttackCount", 20)] {
            assert!(declared.contains(&format!("float local_{output} = (int(local_6.{field}) <= 1) ? 1.0f : (1.0f / (local_6.{field} - 1));")), "{declared}");
        }
        assert!(!declared.contains("local_17")); assert!(!declared.contains("local_21"));
        assert_eq!(super::fold_conditional_values(&declared, &locals, &refs, None, None, &f), declared);
    }

    #[test]
    fn widened_conditional_refuses_live_scratch_wrong_field_type_and_inner_jump_entry() {
        let body = widened_division_body(); let f = widened_division_fixture();
        let refs = RefResolver::from_test_widened_division_fields("int");
        assert_eq!(super::fold_widened_conditional_divisions(&body, &f, &RefResolver::from_test_widened_division_fields("bool")), body);
        for reader in ["PshV4", "NEGf"] {
            let mut live = f.clone(); let mut tail = function(&[(reader, &[15])]).bytecode;
            let cut = disassemble(&live.bytecode).unwrap()[14].offset_dw; tail.extend(live.bytecode.split_off(cut)); live.bytecode.extend(tail);
            assert!(super::fold_widened_conditional_divisions(&body, &live, &refs).contains("    if (int(local_6.MoveCount) <= 1)"));
        }
        let mut entry = f.clone(); let c = disassemble(&entry.bytecode).unwrap(); let end = entry.bytecode.len();
        entry.bytecode.extend(function(&[("JMP", &[])]).bytecode); entry.bytecode[end + 1] = c[10].offset_dw as i32 - end as i32 - 2;
        assert!(super::fold_widened_conditional_divisions(&body, &entry, &refs).contains("    if (int(local_6.MoveCount) <= 1)"));
        let wrong_text = body.replace("local_14 = local_14 - 1;", "local_14 = local_14 - 2;");
        assert_eq!(super::fold_widened_conditional_divisions(&wrong_text, &f, &refs), wrong_text);
    }

