        assert_eq!(keep, HashSet::from([26, 28]));
        let body = "float local_26 = this.Max;\nlocal_26 = local_26 - this.Min;\nfloat local_28 = local_24 - this.Min;\nreturn Math::Mix(1.0, 0.0, local_28 / local_26);\n";
