#[cfg(test)]
mod nested_arithmetic_life_scope_tests {
    use super::*;

    fn inline(body: &str) -> String {
        // The existing candidate set admits this slot/life in the b200 trace. These tests
        // exercise only scope/mention handling; they add no new bytecode permission.
        inline_unnamed_value_temporaries(body, &HashSet::from([(10, 2)]),
            &HashSet::new(), &HashSet::new(), &RefResolver::default(),
            &HashSet::new(), &HashSet::new(), &HashMap::new(), &HashSet::new(),
            &HashSet::new(), &HashSet::new(), &HashSet::new())
    }

    #[test]
    fn an_inner_return_guard_does_not_end_the_outer_value_life() {
        let body = concat!(
            "    float local_10_2 = local_5;\n",
            "    float local_14_4 = local_10_2 * this.Ratio;\n",
            "    if (local_16_2 > local_14_4)\n",
            "    {\n",
            "        return -1000.0;\n",
            "    }\n",
            "    local_14_4 = local_46 + local_48;\n",
            "    local_10_2 = (10.0 * local_14_4) * local_34;\n",
            "    return 1.0 + local_10_2;\n",
        );
        let first = inline(body);
        assert!(!first.contains("float local_10_2 = local_5;"));
        assert!(first.contains("float local_14_4 = local_5 * this.Ratio;"));
        assert!(first.contains("float local_10_2 = (10.0 * local_14_4) * local_34;"));
        // The pipeline already runs this pass twice; the second invocation now sees
        // the tail life alone, so the existing single-use rule can fold the return.
        let second = inline(&first);
        assert!(!second.contains("local_10_2"));
        assert!(second.contains("return 1.0 + ((10.0 * local_14_4) * local_34);"));
    }

    #[test]
    fn leaving_the_owner_block_or_a_conditional_redefinition_still_refuses() {
        for body in [
            "if (First)\n{\n    float local_10_2 = local_5;\n    Consume(local_10_2);\n}\nif (Second)\n{\n    local_10_2 = Other();\n    Consume(local_10_2);\n}\n",
            "    float local_10_2 = local_5;\n    Consume(local_10_2);\n    if (Replace)\n    {\n        local_10_2 = Other();\n        Consume(local_10_2);\n    }\n",
        ] {
            // A later call may independently inline, but the original declaration
            // cannot move into either a sibling block or a conditional new life.
            assert!(inline(body).contains("float local_10_2 = local_5;"));
        }
    }
}

#[cfg(test)]
mod unary_double_chain_tests {
    use super::*;

    fn body() -> String {
        concat!(
            "    float local_16_2 = Previous();\n",
            "    float32 local_33 = 2.0f;\n",
            "    float local_10 = 1.0;\n",
            "    float local_14_2 = local_33;\n",
            "    float local_44 = local_16_2 / local_14_2;\n",
            "    local_14_2 = Math::Abs(local_44);\n",
            "    local_46 = local_10 - local_14_2;\n",
        ).to_owned()
    }

    fn witness() -> HashSet<([i32; 6], String, u64)> {
        HashSet::from([([10, 14, 44, 16, 33, 46], "Math::Abs".into(), 1.0_f64.to_bits())])
    }

    #[test]
    fn exact_chain_folds_both_lives_of_the_widening_slot() {
        let folded = fold_witnessed_unary_double_chain(&body(), &witness());
        assert_eq!(folded, concat!(
            "    float local_16_2 = Previous();\n",
            "    float32 local_33 = 2.0f;\n",
            "    local_46 = 1.0 - Math::Abs(local_16_2 / local_33);\n",
        ));
        assert_eq!(fold_witnessed_unary_double_chain(&body(), &HashSet::new()), body());
    }

    #[test]
    fn chain_rejects_precision_loss_wrong_callee_or_any_extra_use() {
        for source in [
            body().replace("float local_16_2", "float32 local_16_2"),
            body().replace("Math::Abs", "Other::Abs"),
            body().replace("local_16_2 /", "local_18 /"),
            body() + "    Observe(local_44);\n",
            body().replace("    local_14_2 = Math::Abs", "    Observe();\n    local_14_2 = Math::Abs"),
        ] {
            assert_eq!(fold_witnessed_unary_double_chain(&source, &witness()), source);
        }
    }
}

#[cfg(test)]
mod late_boolean_declaration_tests {
    use super::*;

    #[test]
    fn unused_member_carrier_no_longer_blocks_short_circuit_recovery() {
        let body = concat!(
            "    bool local_3;\n",
            "    if (source == nullptr)\n",
            "    {\n",
            "        local_3 = true;\n",
            "    }\n",
            "    else\n",
            "    {\n",
            "        TSubclassOf<UWeaponDefinition> local_6;\n",
            "        local_3 = (this.Weapon == nullptr);\n",
            "    }\n",
            "    if (local_3)\n",
            "    {\n",
            "        return;\n",
            "    }\n",
        );
        let fold = |text: &str| fold_short_circuits(text,
            &BTreeMap::from([(3, "bool".into())]), &RefResolver::default(),
            None, &HashMap::new(), None, &HashSet::new());
        assert_eq!(fold(body), body);
        let cleaned = drop_unused_declarations(body, &HashSet::new(), &HashSet::new());
        let folded = fold(&cleaned);
        assert!(folded.contains("local_3 = source == nullptr || (this.Weapon == nullptr);"), "{folded}");

        // Initializers with work and bytecode-witnessed unused literals stay in the arm.
        for (declaration, keep) in [
            ("TSubclassOf<UWeaponDefinition> local_6 = MakeClass();", HashSet::new()),
            ("float local_6 = 1.0;", HashSet::from([6])),
        ] {
            let source = body.replace("TSubclassOf<UWeaponDefinition> local_6;", declaration);
            let cleaned = drop_unused_declarations(&source, &keep, &HashSet::new());
            assert_eq!(cleaned, source);
            assert_eq!(fold(&cleaned), source);
        }
    }
}

#[cfg(test)]
mod declared_condition_loop_tests {
    use super::*;

    fn source() -> String {
        concat!(
            "    bool local_10;\n",
            "    if (this.AttackToDodge == nullptr)\n",
            "    {\n",
            "        local_10 = false;\n",
            "    }\n",
            "    else\n",
            "    {\n",
            "        local_10 = this.AttackToDodge.GetEstimatedTimeLeftUntilImpact() <= 0.0 && (this.AttackToDodge.GetEstimatedTimeLeftUntilImpact() > 0.5);\n",
            "    }\n",
            "    if (local_10)\n",
            "    {\n",
            "        this.WaitOneTick();\n",
            "        //__gore_back_edge\n",
            "    }\n",
            "    Super::DoTask_Implementation();\n",
            "    return;\n",
        ).into()
    }

    fn fold(body: &str) -> String {
        fold_short_circuits(body, &BTreeMap::from([(10, "bool".into())]),
            &RefResolver::default(), None, &HashMap::new(), None, &HashSet::new())
    }

    #[test]
    fn marked_loop_keeps_its_declared_nested_condition() {
        // Real late pipeline: the inner bool arm is already folded, and the
        // declaration sink has joined the bare carrier to the rendered body.
        let folded = fold(&source());
        assert!(folded.contains("local_10 = this.AttackToDodge != nullptr && (this.AttackToDodge.GetEstimatedTimeLeftUntilImpact() <= 0.0 && (this.AttackToDodge.GetEstimatedTimeLeftUntilImpact() > 0.5));"));
        let recovered = recover_condition_loops(&rejoin_short_circuit_chains(
            &join_short_circuit_chains(&folded)));
        let output = drop_unused_declarations(&recovered, &HashSet::new(), &HashSet::new());
        assert_eq!(output, concat!(
            "    while (this.AttackToDodge != nullptr && (this.AttackToDodge.GetEstimatedTimeLeftUntilImpact() <= 0.0 && (this.AttackToDodge.GetEstimatedTimeLeftUntilImpact() > 0.5)))\n",
            "    {\n",
            "        this.WaitOneTick();\n",
            "    }\n",
            "    Super::DoTask_Implementation();\n",
            "    return;\n",
        ));
        // The old undeclared-carrier path continues to work.
        assert!(recover_condition_loops(&folded.replace("    bool local_10;\n", ""))
            .contains("    while (this.AttackToDodge != nullptr && ("));
    }

    #[test]
    fn compound_target_recovery_defers_controls_and_respects_real_loop_boundaries() {
        let outer = source().replace("//__gore_back_edge", "//__gore_back_edge 100");
        let nested = concat!(
            "        if (Skip)\n        {\n",
            "            if (Again)\n            {\n",
            "                Step();\n                //__gore_back_edge 100\n            }\n",
            "            this.WaitOneTick();\n            //__gore_back_edge 100\n        }\n",
        );
        let body = outer.replace("        this.WaitOneTick();\n", nested);
        let recover = |body: &str| recover_condition_loops(&rejoin_short_circuit_chains(
            &join_short_circuit_chains(&fold(body))));
        let recovered = recover(&body);
        assert_eq!(recovered.matches("while (").count(), 1, "{recovered}");
        assert_eq!(recovered.matches("continue;").count(), 2, "{recovered}");
        assert!(recovered.contains("if (Skip)") && recovered.contains("if (Again)"), "{recovered}");
        assert!(!recovered.contains("__gore_"), "internal marker escaped:\n{recovered}");

        // The outer carrier remains observable, so the existing fold refuses it.
        // Even the two nested same-target recoveries must wait: neither may add
        // a continue before learning whether this actual outer loop recovers.
        for trailing in ["", "        AfterMarker();\n"] {
            let marked = body.replace("        //__gore_back_edge 100\n    }\n",
                &format!("        //__gore_back_edge 100\n{trailing}    }}\n"));
            assert!(trailing.is_empty() || marked.contains("AfterMarker();"));
            let refused = recover(&format!("{marked}    Read(local_10);\n"));
            assert!(refused.contains("if (local_10)"), "outer carrier unexpectedly folded:\n{refused}");
            assert!(refused.contains("while (Skip)") && refused.contains("while (Again)"), "{refused}");
            assert!(!refused.contains("continue;") && !refused.contains("break;"), "{refused}");
            assert!(!refused.contains("__gore_"), "{refused}");
        }

        let guarded_continue = concat!(
            "        if (Outside)\n        {\n            Step();\n",
            "            //__gore_back_edge 100\n        }\n",
        );
        for (head, latch) in [
            ("while (Other)", ""),
            ("for (; Other;)", ""),
            ("if (Other)", "            //__gore_back_edge 200\n"),
        ] {
            let barrier = format!(concat!(
                "        {}\n        {{\n",
                "            if (Blocked)\n            {{\n",
                "                Step();\n                //__gore_back_edge 100\n            }}\n",
                "            Tick();\n{}        }}\n",
            ), head, latch);
            let body = outer.replace("        this.WaitOneTick();\n",
                &format!("{guarded_continue}{barrier}        this.WaitOneTick();\n"));
            let recovered = recover(&body);
            assert!(recovered.contains("if (Outside)"), "{recovered}");
            assert_eq!(recovered.matches("continue;").count(), 1, "{recovered}");
            assert!(recovered.contains("while (Blocked)") && !recovered.contains("if (Blocked)"),
                "same-target conversion crossed {head}:\n{recovered}");
            assert!(!recovered.contains("__gore_"), "{recovered}");
        }
    }

    #[test]
    fn pending_break_recovery_requires_exact_exit_success_and_same_loop_boundary() {
        let outer = source().replace("//__gore_back_edge", "//__gore_back_edge 100 900");
        let nested = concat!(
            "        if (Skip)\n        {\n",
            "            if (Again)\n            {\n",
            "                if (Stop)\n                {\n",
            "                    //__gore_loop_break 100 900\n                }\n",
            "                else\n                {\n                    Step();\n                }\n",
            "                //__gore_back_edge 100\n            }\n",
            "            this.WaitOneTick();\n            //__gore_back_edge 100\n        }\n",
        );
        let body = outer.replace("        this.WaitOneTick();\n", nested);
        let recover = |body: &str| recover_condition_loops(&rejoin_short_circuit_chains(
            &join_short_circuit_chains(&fold(body))));
        for (pair, count) in [("100 900", 1), ("100 901", 0), ("200 900", 0)] {
            let recovered = recover(&body.replace("//__gore_loop_break 100 900",
                &format!("//__gore_loop_break {pair}")));
            assert_eq!(recovered.matches("break;").count(), count, "{recovered}");
            assert_eq!(recovered.matches("continue;").count(), 2, "{recovered}");
            assert_eq!(recovered.matches("while (").count(), 1, "{recovered}");
            assert!(!recovered.contains("__gore_"), "{recovered}");
        }
        // A live outer carrier refuses recovery even after both same-target
        // descendants recovered. Trailing cleanup must not weaken that boundary.
        for trailing in ["", "        AfterMarker();\n"] {
            let marked = body.replace("        //__gore_back_edge 100 900\n    }\n",
                &format!("        //__gore_back_edge 100 900\n{trailing}    }}\n"));
            let refused = recover(&format!("{marked}    Read(local_10);\n"));
            assert!(refused.contains("if (local_10)"), "{refused}");
            assert!(!refused.contains("break;") && !refused.contains("continue;"), "{refused}");
            assert!(!refused.contains("__gore_"), "{refused}");
        }
        for (head, latch) in [("while (Other)", ""), ("for (; Other;)", ""),
            ("if (Other)", "            //__gore_back_edge 200 950\n")]
        {
            let barrier = format!(concat!(
                "        if (Outside)\n        {{\n            //__gore_loop_break 100 900\n        }}\n",
                "        {}\n        {{\n            if (Stop)\n            {{\n",
                "                //__gore_loop_break 100 900\n            }}\n{}        }}\n",
            ), head, latch);
            let recovered = recover(&outer.replace("        this.WaitOneTick();\n", &barrier));
            assert_eq!(recovered.matches("break;").count(), 1, "crossed {head}:\n{recovered}");
            assert!(!recovered.contains("__gore_"), "{recovered}");
        }
        let plain = recover(&body.replace("//__gore_back_edge 100 900", "//__gore_back_edge 100"));
        assert!(!plain.contains("break;"), "no exit provenance:\n{plain}");
    }

    #[test]
    fn declaration_exception_does_not_hide_other_lives_or_unmarked_ifs() {
        let folded = fold(&source());
        for bad in [
            format!("{folded}    Read(local_10);\n"),
            format!("{folded}    local_10 = true;\n"),
            folded.replace("    bool local_10;", "    int local_10;"),
            folded.replace("    bool local_10;", "        bool local_10;"),
            folded.replace("    bool local_10;", "    bool local_10;\n    Before();"),
        ] {
            let recovered = recover_condition_loops(&bad);
            assert!(!recovered.contains("while ("), "{recovered}");
            assert!(recovered.contains("if (local_10)"), "{recovered}");
        }
        let unmarked = source().replace("        //__gore_back_edge\n", "");
        let plain = recover_condition_loops(&fold(&unmarked));
        assert!(plain.contains("if (local_10)"));
        assert!(plain.contains("local_10 = this.AttackToDodge != nullptr && this.AttackToDodge.GetEstimatedTimeLeftUntilImpact() <= 0.0 && ("));
        let other = source().replace("    if (local_10)", "    if (local_11)");
        assert!(!fold(&other).contains("local_10 = this.AttackToDodge != nullptr && ("));
        // A nested marker is not the following if's own latch.
        let nested = source().replace("        this.WaitOneTick();\n        //__gore_back_edge\n",
            "        if (Other)\n        {\n            this.WaitOneTick();\n            //__gore_back_edge\n        }\n");
        assert!(!fold(&nested).contains("local_10 = this.AttackToDodge != nullptr && ("));
    }
}

#[cfg(test)]
mod short_circuit_life_name_tests {
    use super::*;

    fn source(name: &str, other: &str) -> String {
        format!(concat!(
            "    if ({0} && Other != nullptr)\n",
            "    {{\n",
            "        {0} = true;\n",
            "    }}\n",
            "    else\n",
            "    {{\n",
            "        {1} = Me != nullptr && Other != nullptr;\n",
            "    }}\n",
        ), name, other)
    }

    fn fold(body: &str, locals: &BTreeMap<i32, String>) -> String {
        fold_short_circuits(body, locals, &RefResolver::default(), None, &HashMap::new(), None, &HashSet::new())
    }

    #[test]
    fn late_bool_carriers_fold_with_their_full_life_name() {
        let locals = BTreeMap::from([(3, "bool".to_owned())]);
        for name in ["local_3", "local_3_2", "local_3_12"] {
            let body = format!("    bool {name};\n{}", source(name, name));
            assert_eq!(fold(&body, &locals), format!(
                "    bool {name};\n    {name} = ({name} && Other != nullptr) || (Me != nullptr && Other != nullptr);\n"
            ));
        }
    }

    #[test]
    fn suffix_support_keeps_boolean_and_exact_target_guards() {
        let body = source("local_3_2", "local_3_2");
        for locals in [BTreeMap::new(), BTreeMap::from([(3, "int".to_owned())])] {
            assert_eq!(fold(&body, &locals), body);
        }
        let locals = BTreeMap::from([(3, "bool".to_owned())]);
        for body in [
            source("local_3_2", "local_3_3"),
            source("local_3_2_extra", "local_3_2_extra"),
            source("local_3_2", "local_3_2").replace(
                "Me != nullptr && Other != nullptr", "local_3_2 && Other != nullptr"),
        ] {
            let body = format!("    bool local_3_2;\n{body}");
            assert_eq!(fold(&body, &locals), body);
        }
    }

    #[test]
    fn later_life_uses_its_declaration_and_never_inherits_the_first_type() {
        for (first, later, folds) in [("int", "bool", true), ("bool", "int", false)] {
            let locals = BTreeMap::from([(3, first.to_owned())]);
            let body = format!("    {first} local_3;\n    {later} local_3_2;\n{}",
                source("local_3_2", "local_3_2"));
            assert_eq!(!fold(&body, &locals).contains("else"), folds);
            let condition = format!("    {first} local_3;\n    {later} local_3_2 = Me != nullptr;\n    if (local_3_2)\n    {{\n        return false;\n    }}\n");
            let folded = fold_condition_temporaries(&condition, &locals, &RefResolver::default(),
                None, &HashSet::new(), &HashSet::new(), false);
            assert_eq!(!folded.contains("if (local_3_2)"), folds);
        }
        let locals = BTreeMap::from([(3, "bool".to_owned())]);
        let unknown = source("local_3_2", "local_3_2");
        assert_eq!(fold(&unknown, &locals), unknown);
        let unknown = "    local_3_2 = Me != nullptr;\n    if (local_3_2)\n    {\n        return false;\n    }\n";
        assert_eq!(fold_condition_temporaries(unknown, &locals, &RefResolver::default(),
            None, &HashSet::new(), &HashSet::new(), false), unknown);
    }

    #[test]
    fn existing_bool_passes_accept_a_suffixed_diamond_and_negation() {
        let locals = BTreeMap::from([(3, "bool".to_owned())]);
        let input = format!("    bool local_3_2 = Me != nullptr && Ready != nullptr;\n{}    local_3_2 = !local_3_2;\n    if (local_3_2)\n    {{\n        return false;\n    }}\n",
            source("local_3_2", "local_3_2"));
        // Existing merge_self_assignments understands life suffixes already. The
        // type check of the following whole-condition fold was the next blocker.
        let combined = merge_self_assignments(&fold(&input, &locals), &locals);
        let output = fold_condition_temporaries(&combined, &locals, &RefResolver::default(),
            None, &HashSet::new(), &HashSet::new(), false);
        assert!(!output.contains("local_3_2"), "{output}");
        assert!(output.contains("if (!("), "{output}");
        assert!(output.contains(" || "), "{output}");
        assert_eq!(fold_condition_temporaries(&combined, &locals, &RefResolver::default(),
            None, &HashSet::from([3]), &HashSet::new(), false), combined);
    }

    #[test]
    fn boolean_literal_equality_restores_the_compilers_normalization_pair() {
        let source = "local_1 = Ready();\nlocal_1 = !local_1;\nlocal_2 = false;\nlocal_2 = !local_2;\nif (local_1 == local_2)\n{\n    Use();\n}\n";
        let expected = "local_1 = Ready();\nlocal_2 = false;\nif (local_1 == local_2)\n{\n    Use();\n}\n";
        assert_eq!(fold_negated_stores(source, &HashSet::new()), expected);
        for op in ["==", "!="] {
            let source = source.replace("==", op).replace("false", "true");
            assert_eq!(fold_negated_stores(&source, &HashSet::new()), expected.replace("==", op).replace("false", "true"));
        }
        for source in [source.replace("false", "Other()"), source.replace("==", "&&"),
            format!("{source}Use(local_1);\n"), source.replace("if (", "    if (")] {
            let folded = fold_negated_stores(&source, &HashSet::new());
            assert!(folded.contains("local_1 = !(Ready());"), "{folded}");
        }
    }

    #[test]
    fn boolean_normalization_pair_ignores_independently_overwritten_lives() {
        let prefix = "local_1 = Before();\nif (local_1)\n{\n    return;\n}\n";
        let pair = "local_1 = Ready();\nlocal_1 = !local_1;\nlocal_2 = true;\nlocal_2 = !local_2;\nif (local_1 == local_2)\n{\n    return;\n}\n";
        let tail = "local_2 = true;\nSave(local_2);\n";
        let source = format!("{prefix}{pair}{tail}");
        let expected = source.replace("local_1 = !local_1;\n", "").replace("local_2 = !local_2;\n", "");
        assert_eq!(fold_negated_stores(&source, &HashSet::new()), expected);
        for source in [source.replace("{\n    return;\n}\nlocal_2 = true;", "{\n    Read(local_1);\n    return;\n}\nlocal_2 = true;"),
            format!("{prefix}{pair}if (Other)\n{{\n    local_2 = true;\n}}\nSave(local_2);\n"),
            format!("while (local_1)\n{{\n{}}}\n", source.lines().map(|l| format!("    {l}\n")).collect::<String>())] {
            assert!(fold_negated_stores(&source, &HashSet::new()).contains("local_2 = !(true);"), "{source}");
        }
    }

    #[test]
    fn suffixed_boolean_negation_does_not_enable_numeric_negation() {
        let input = "    local_3_2 = Me != nullptr || Other != nullptr;\n    local_3_2 = !local_3_2;\n";
        let output = fold_negated_stores(input, &HashSet::new());
        assert_eq!(output, "    local_3_2 = !(Me != nullptr || Other != nullptr);\n");
        let numeric = "    local_3_2 = Value();\n    local_3_2 = -local_3_2;\n";
        assert_eq!(fold_negated_stores(numeric, &HashSet::new()), numeric);
    }
}

#[cfg(test)]
mod parameter_member_store_alias_tests {
    use super::*;

    fn fold(body: &str, ty: &str) -> String {
        fold_member_read_temporaries(body, &HashSet::new(), &HashSet::new(),
            &BTreeMap::from([(2, ty.to_owned())]), None,
            &HashMap::from([("Data".to_owned(), ty.to_owned())]),
            &RefResolver::default(), &HashMap::new(), false, &HashSet::new(), &HashSet::new(), &HashMap::new())
    }

    #[test]
    fn member_writes_keep_the_parameter_copy_receiver() {
        for ty in ["USpellExecutionValidatorDataDefault", "FValue"] {
            for declaration in ["local_2 = Data;".to_owned(), format!("{ty} local_2 = Data;")] {
                let body = format!("    {declaration}\n    local_2.SourceActor = SourceActor;\n    return;\n");
                assert_eq!(fold(&body, ty), body);
            }
        }
    }

    #[test]
    fn read_aliases_still_fold_without_a_member_store() {
        let body = "    local_2 = Data;\n    return local_2;\n";
        assert_eq!(fold(body, "UValue"), "    return Data;\n");
        // A member write unrelated to the alias is not a reason to keep it.
        let body = "    local_2 = Data;\n    Other.Value = local_2;\n";
        assert_eq!(fold(body, "UValue"), "    Other.Value = Data;\n");
    }
}

#[cfg(test)]
mod out_argument_read_order_tests {
    use super::*;

    fn late(body: &str, refs: &RefResolver) -> String {
        inline_unnamed_value_temporaries(body, &HashSet::from([(55, 1), (56, 1)]),
            &HashSet::new(), &HashSet::new(), refs, &HashSet::new(), &HashSet::new(),
            &HashMap::new(), &HashSet::new(), &HashSet::new(), &HashSet::new(), &HashSet::new())
    }

    #[test]
    fn two_eager_attribute_calls_stay_before_their_out_flag_condition() {
        let refs = RefResolver::from_test_out_argument_read_order(false);
        // This is the real pipeline shape after merge_self_assignments. The flags
        // occur before both result uses; neither getter may become conditional.
        let body = concat!(
            "    bool local_49 = false;\n",
            "    bool local_51 = false;\n",
            "    float32 local_55 = ReadAttribute(this.GetComponent(), local_20, local_49);\n",
            "    float32 local_56 = ReadAttribute(this.GetComponent(), local_34, local_51);\n",
            "    bool local_50 = (!local_51 || !local_49) || (local_55 < local_56 * this.Ratio);\n",
            "    if (local_50)\n    {\n        return false;\n    }\n");
        let first = late(body, &refs);
        assert_eq!(first, body);
        assert_eq!(late(&first, &refs), body);

        // The early operand inliner observes the same dependency after any
        // earlier pass has already collapsed the boolean carrier.
        let early = "    local_55 = ReadAttribute(this.GetComponent(), local_20, local_49);\n    if (!local_49 || local_55 < 0.0)\n    {\n        return false;\n    }\n";
        let locals = BTreeMap::from([(55, "float32".into()), (49, "bool".into())]);
        let out = inline_call_argument_temporaries(early, &refs, &locals, None, true,
            &HashMap::from([(55, "float32".into())]), &HashSet::new(), &HashSet::new(),
            &HashSet::new(), &HashSet::new(), &HashSet::new(), &HashSet::new(),
            &HashSet::new(), &HashSet::new(), &HashMap::new(), &HashSet::new(), &HashSet::new());
        assert_eq!(out, early);
    }

    #[test]
    fn const_unknown_or_different_local_life_does_not_gain_a_keep() {
        let mutable = RefResolver::from_test_out_argument_read_order(false);
        let readonly = RefResolver::from_test_out_argument_read_order(true);
        let value = "ReadAttribute(this.GetComponent(), local_20, local_49_2)";
        let consumer = "return !local_49_2 || local_55 < 0.0;";
        assert!(inline_crosses_out_argument_read(value, "local_55", consumer, &mutable));
        assert!(!inline_crosses_out_argument_read(value, "local_55", consumer, &readonly));
        assert!(!inline_crosses_out_argument_read(value, "local_55", consumer, &RefResolver::default()));
        assert!(!inline_crosses_out_argument_read(value, "local_55", "return !local_49 || local_55 < 0.0;", &mutable));
        assert!(!inline_crosses_out_argument_read(value, "local_55", "return local_55 < 0.0 || !local_49_2;", &mutable));
        assert!(!inline_crosses_out_argument_read(value, "local_55", "local_49_2 = local_55 < 0.0;", &mutable));
    }
}

#[cfg(test)]
mod nested_call_site_argument_tests {
    use super::*;

    fn inline(body: &str, refs: &RefResolver) -> String {
        inline_call_argument_temporaries(body, refs,
            &BTreeMap::from([(6, "AGothicCharacter".into())]), None, true,
            &HashMap::new(), &HashSet::new(), &HashSet::new(), &HashSet::new(),
            &HashSet::new(), &HashSet::new(), &HashSet::new(), &HashSet::new(),
            &HashSet::new(), &HashMap::new(), &HashSet::new(), &HashSet::new())
    }

    #[test]
    fn cast_argument_inside_receiver_chain_and_product_is_visible() {
        let statement = "    UController::Get().Set(ReadAttribute(this, 0, local_6) * 2.0f);\n";
        let body = format!("    local_6 = Cast<AGothicCharacter>(this.GetAvatar());\n{statement}");
        let refs = RefResolver::from_test_out_argument_read_order(true);
        assert_eq!(inline(&body, &refs),
            "    UController::Get().Set(ReadAttribute(this, 0, Cast<AGothicCharacter>(this.GetAvatar())) * 2.0f);\n");
        // A successful old single-call path keeps its existing argument order.
        assert_eq!(call_sites("Use(ReadAttribute(this, 0, local_6));"), vec![
            ("Use".into(), vec!["ReadAttribute(this, 0, local_6)".into()]),
            ("ReadAttribute".into(), vec!["this".into(), "0".into(), "local_6".into()])]);
    }

    #[test]
    fn nested_fallback_does_not_reclassify_stored_or_tested_numeric_chains() {
        // HitsReceived: early argument inlining exposed the zero-seeded accumulator
        // to collapse_single_use_accumulators, dropping its original SetV4/ADDi.
        let accumulated = "local_1 = local_1 + local_4.GetPerception().GetMemory().Filter().FilterAffectedCharacterIs(this.GetSelf()).FilterRecent(local_25).GetCount();";
        // CompleteChapter: the earlier merge concealed the intermediate double
        // declaration, so the late inliner changed iTOd/dTOf into iTOf.
        let stored = "local_2 = local_10.WithTag(this.RequiredMemoryTag).WithMagnitude(local_13).WithClass(this.RequiredClass).GetCount();";
        let tested = "if (LongTermMemoryComponent.Filter().WithTag(this.RequiredMemoryTag).WithMagnitude(float32(local_12)).WithClass(this.RequiredClass).GetCount() == 0)";
        for line in [accumulated, stored, tested,
            "return this.Containers.opIndex(local_2).Groups.opIndex(local_8);"] {
            assert!(call_sites(line).is_empty(), "{line}");
        }
        // The old successful single-call path, including assignment and return
        // consumers, keeps its existing typed argument handling.
        for line in ["local_13 = float32(local_12);", "return float32(local_12);"] {
            assert_eq!(call_sites(line), vec![("float32".into(), vec!["local_12".into()])]);
        }
        // The existing cast_argument_inside_receiver_chain_and_product_is_visible
        // test exercises the complete Health statement through the actual inliner.
        assert!(call_sites("UController::Get().Set(ReadAttribute(this, 0, local_6) * 2.0f);")
            .iter().any(|(name, args)| name == "ReadAttribute" && args.last().is_some_and(|arg| arg == "local_6")));
    }

    #[test]
    fn fallback_ignores_string_calls_and_preserves_parameter_gates() {
        assert!(call_sites("return this.Containers.opIndex(local_2).Groups.opIndex(local_8);").is_empty());
        assert_eq!(call_sites("return Use(local_6);"), vec![("Use".into(), vec!["local_6".into()])]);
        let sites = call_sites(r#"UController::Get().Set("Fake(\"local_9\",)", ReadAttribute(this, 0, local_6) * 2.0f);"#);
        assert_eq!(sites, vec![("Get".into(), vec![]),
            ("ReadAttribute".into(), vec!["this".into(), "0".into(), "local_6".into()])]);
        let body = "    local_6 = Cast<AGothicCharacter>(this.GetAvatar());\n    UController::Get().Set(ReadAttribute(this, 0, local_6) * 2.0f);\n";
        assert_eq!(inline(body, &RefResolver::from_test_out_argument_read_order(false)), body);
        assert_eq!(inline(body, &RefResolver::default()), body);
    }
}

#[cfg(test)]
mod integer_bool_merge_carrier_tests {
    use super::*;

    fn body(other: &str) -> String {
        format!("    int local_3;\n    if (this.Count == 0)\n    {{\n        local_3 = 1;\n    }}\n    else\n    {{\n{other}    }}\n    if (local_3 != 0)\n    {{\n        return;\n    }}\n")
    }

    #[test]
    fn integer_spelled_or_carriers_need_a_boolean_other_arm() {
        let fields = HashMap::from([("Lost".into(), "bool".into())]);
        let direct = body("        local_3 = this.Lost;\n");
        assert_eq!(fold_carrier_if_else(&direct, Some(&fields)),
            "    if (this.Count == 0 || this.Lost)\n    {\n        return;\n    }\n");
        for expression in ["(this.Index > this.Count)", "(this.Component == nullptr)"] {
            let source = body(&format!("        bool local_7 = {expression};\n        local_3 = local_7;\n"));
            let expected = format!("    if (this.Count == 0 || {expression})\n    {{\n        return;\n    }}\n");
            assert_eq!(fold_carrier_if_else(&source, None), expected);
            assert_eq!(fold_carrier_if_else(&expected, None), expected);
        }
        assert_eq!(fold_carrier_if_else(&direct, None), direct);
        assert_eq!(fold_carrier_if_else(&direct,
            Some(&HashMap::from([("Lost".into(), "int".into())]))), direct);
    }

    fn reused_bool_or_body() -> String {
        "    int local_3;\n    bool local_4;\n    if (Other == nullptr)\n    {\n        local_3 = 1;\n    }\n    else\n    {\n        local_4 = Other.Active;\n        local_3 = local_4;\n    }\n    if (local_3 != 0 || Other.Completed)\n    {\n        return false;\n    }\n    this.Other = Other;\n    local_4 = true;\n    this.Other.Activated = local_4;\n    return true;\n".into()
    }

    #[test]
    fn reused_bool_first_life_rejoins_before_its_later_literal_store() {
        let source = reused_bool_or_body();
        let direct_literals = HashSet::from([4]);
        assert_eq!(inline_bool_literal_temporaries(&source, &direct_literals), source,
            "the pre-existing first-use guard must still reject the earlier bool life");
        let folded = fold_carrier_if_else(&source, None);
        assert!(folded.contains("if (Other == nullptr || Other.Active || Other.Completed)"), "{folded}");
        assert!(folded.contains("bool local_4;") && folded.contains("local_4 = true;"), "{folded}");
        assert!(!folded.contains("local_3") && !folded.contains("local_4 = Other.Active"), "{folded}");
        let literal = inline_bool_literal_temporaries(&folded, &direct_literals);
        let final_body = drop_unused_declarations(&literal, &HashSet::new(), &HashSet::new());
        assert_eq!(final_body, "    if (Other == nullptr || Other.Active || Other.Completed)\n    {\n        return false;\n    }\n    this.Other = Other;\n    this.Other.Activated = true;\n    return true;\n");
        assert_eq!(fold_carrier_if_else(&final_body, None), final_body);
        // The new test-tail shape also composes with the old, independently
        // declared and closed boolean alternative; the ordinary path stays intact.
        let old = body("        bool local_7 = (this.Index > this.Count);\n        local_3 = local_7;\n");
        let extended = old.replace("if (local_3 != 0)", "if (local_3 != 0 || this.More)");
        assert_eq!(fold_carrier_if_else(&extended, None),
            fold_carrier_if_else(&old, None).replace("this.Count))", "this.Count) || this.More)"));
    }

    #[test]
    fn reused_bool_merge_requires_a_dominating_declaration_and_dead_first_life() {
        let source = reused_bool_or_body();
        for rejected in [
            source.replace("bool local_4;", "int local_4;"),
            source.replace("bool local_4;", "bool& local_4;"),
            source.replace("    bool local_4;\n", ""),
            source.replace("    bool local_4;", "    if (Ready())\n    {\n        bool local_4;\n    }"),
            source.replace("    if (Other == nullptr)", "    Use(local_4);\n    if (Other == nullptr)"),
            source.replace("        local_3 = local_4;", "        Use(local_4);\n        local_3 = local_4;"),
            source.replace("    local_4 = true;", "    Use(local_4);\n    local_4 = true;"),
            source.replace("    local_4 = true;", "    local_4 = !local_4;"),
            source.replace("    local_4 = true;", "    if (Ready())\n    {\n        local_4 = true;\n    }"),
            source.replace("local_3 = 1;", "local_3 = 2;"),
            source.replace("local_3 != 0 || Other.Completed", "local_3 != 0 && Other.Completed"),
            source.replace("local_3 != 0 || Other.Completed", "Ready(local_3 != 0) || Other.Completed"),
            source.replace("local_3 != 0 || Other.Completed", "local_3 != 0 || Other.Completed || local_3 != 0"),
        ] {
            assert_eq!(fold_carrier_if_else(&rejected, None), rejected);
        }
    }

    #[test]
    fn integer_merge_does_not_consume_another_local_life_or_numeric_arm() {
        let source = body("        bool local_7 = (this.Component == nullptr);\n        local_3 = local_7;\n");
        for suffix in ["    Use(local_7);\n", "    local_7 = true;\n", "    Use(local_3);\n"] {
            let reused = format!("{source}{suffix}");
            assert_eq!(fold_carrier_if_else(&reused, None), reused);
        }
        for rejected in [source.replace("bool local_7", "int local_7"),
            source.replace("local_3 = 1", "local_3 = 2"),
            source.replace("if (local_3 != 0)", "if (local_3 > 0)"),
            source.replace("int local_3;", "bool local_3;")] {
            assert_eq!(fold_carrier_if_else(&rejected, None), rejected);
        }
    }
}

#[cfg(test)]
mod named_feeder_order_tests {
    use super::*;

    #[test]
    fn a_named_eager_bool_feeder_keeps_the_preceding_call_in_order() {
        let refs = RefResolver::from_test_eager_bool_calls(0x41);
        let locals = BTreeMap::from([(6, "bool".into()), (9, "bool".into())]);
        let types = HashMap::from([(6, "bool".into()), (9, "bool".into())]);
        let empty = HashSet::new();
        let body = "local_9 = Other();\nlocal_6 = Saved();\nif (local_9 && !(local_6))\n";
        let fold = |sites: &HashSet<(i32, String)>| inline_call_argument_temporaries(body, &refs, &locals, None, true,
            &types, &empty, &empty, &empty, &empty, &empty, &empty, &empty, &empty,
            &HashMap::new(), &empty, sites);
        assert_eq!(fold(&HashSet::from([(6, "Saved".into())])), body);
        // Another callee's life on slot 6 does not preserve this feeder.
        assert!(!fold(&HashSet::from([(6, "Earlier".into())])).contains("local_9 = Other();"));
        // The late inliner must observe the same barrier after declarations appear.
        let declared = body.replace("local_9 =", "bool local_9 =").replace("local_6 =", "bool local_6 =");
        let late = |sites: &HashSet<(i32, String)>| inline_unnamed_value_temporaries(
            &declared, &HashSet::from([(6, 1), (9, 1)]), &empty, &empty, &refs,
            &empty, &empty, &HashMap::new(), sites, &empty, &empty, &empty);
        assert_eq!(late(&HashSet::from([(6, "Saved".into())])), declared);
        assert!(!late(&HashSet::from([(6, "Earlier".into())])).contains("bool local_9 = Other();"));
    }
}

#[cfg(test)]
mod comparison_carrier_return_tests {
    use super::*;

    fn body(condition: &str, alternative: &str) -> String {
        format!("    int local_7;\n    if ({condition})\n    {{\n        local_7 = 0;\n    }}\n    else\n    {{\n        bool local_8 = ({alternative});\n        local_7 = local_8;\n    }}\n    return (local_7 != 0);\n")
    }

    #[test]
    fn comparison_carrier_returns_recover_direct_and_relations() {
        for (condition, inverse, alternative) in [
            ("CenterArea.Distance(TargetLocation) < this.m_MinInnerDistance",
             "CenterArea.Distance(TargetLocation) >= this.m_MinInnerDistance",
             "CenterArea.Distance(TargetLocation) <= this.m_MaxOuterDistance"),
            ("CenterArea.Distance(TargetLocation) < local_4",
             "CenterArea.Distance(TargetLocation) >= local_4", "CenterArea.Distance(TargetLocation) <= local_6"),
            ("local_2 != this.FindGroupAndTeamOf(Groups, CharacterStateB, local_3)",
             "local_2 == this.FindGroupAndTeamOf(Groups, CharacterStateB, local_3)", "local_1 != local_3"),
        ] {
            let input = body(condition, alternative);
            let expected = format!("    return {inverse} && ({alternative});\n");
            assert_eq!(fold_carrier_if_else(&input, None), expected);
            assert_eq!(fold_carrier_if_else(&expected, None), expected);
        }
    }

    #[test]
    fn comparison_carrier_return_keeps_types_lives_and_nested_conditions() {
        let input = body("a < b", "c <= d");
        for rejected in [input.replace("int local_7", "float local_7"),
            input.replace("int local_7", "bool local_7"),
            input.replace("bool local_8", "int local_8"),
            input.replace("local_7 = 0", "local_7 = 1"),
            input.replace("return (local_7 != 0);", "return (local_7 > 0);"),
            format!("{input}    Use(local_7);\n"), format!("{input}    Use(local_8);\n"),
            body("Check(a < b)", "c <= d"), body("a < b && Ready()", "c <= d"),
            body("a < b ? Ready() : Done()", "c <= d"),
            body("this.Name == n\"a < b\"", "c <= d"), body("Ready()", "c <= d"),
        ] {
            assert_eq!(fold_carrier_if_else(&rejected, None), rejected);
        }
    }
}
